import{P as e}from"./data-patterns-BpualT9q.js";const o=JSON.parse(`[{"stage":"greetings-introductions","title":"I'm, My name is: giới thiệu bản thân","points":["\\"My name is Lan\\" nghĩa là \\"Tên tôi là Lan\\". \\"My\\" là từ chỉ sở hữu (của tôi), luôn đứng trước danh từ.","\\"I'm\\" là viết tắt của \\"I am\\". Tiếng Anh không được bỏ \\"am\\" như tiếng Việt: \\"I'm from Vietnam\\", không phải \\"I from Vietnam\\".","\\"I'm from + nơi\\" nói về quê hương hoặc đất nước của bạn. \\"Nice to meet you\\" là câu cố định khi gặp ai lần đầu."],"examples":[{"en":"My name is Lan.","vi":"Tên tôi là Lan."},{"en":"Nice to meet you, Tom.","vi":"Rất vui được gặp bạn, Tom."},{"en":"I'm from Vietnam.","vi":"Tôi đến từ Việt Nam."}],"mistake":{"wrong":"I from Vietnam.","right":"I'm from Vietnam.","why":"Câu tiếng Anh cần động từ to be (am/is/are). Tiếng Việt bỏ được, tiếng Anh thì không."},"lessons":[]},{"stage":"family","title":"This is my..., I have... nói về gia đình","points":["\\"This is my + người thân\\" dùng để giới thiệu ai đó: \\"This is my mother\\". \\"My\\" đứng trước danh từ, không thêm \\"the\\".","\\"My father is a teacher\\": giữa chủ ngữ và nghề nghiệp phải có \\"is\\". Nghề nghiệp ở số ít cần thêm \\"a\\" hoặc \\"an\\".","\\"I have two sisters\\": từ hai người trở lên thì danh từ thêm -s (sisters, brothers). Một người thì dùng \\"a\\": \\"I have a brother\\"."],"examples":[{"en":"This is my mother.","vi":"Đây là mẹ tôi."},{"en":"My father is a doctor.","vi":"Bố tôi là bác sĩ."},{"en":"I have two sisters.","vi":"Tôi có hai chị em gái."}],"mistake":{"wrong":"My father teacher.","right":"My father is a teacher.","why":"Tiếng Anh cần \\"is\\" nối chủ ngữ với nghề nghiệp, và nghề ở số ít cần \\"a/an\\"."},"lessons":[{"id":"ch24-l01","title":"Mạo từ bất định"},{"id":"ch15-l15","title":"Hầu hết các danh từ số nhiều thường thêm s ở cuối."}]},{"stage":"personal-info","title":"I'm 25 years old: tuổi, nơi ở, ngôn ngữ","points":["Nói tuổi bằng \\"be\\": \\"I'm 25 years old\\". Tiếng Việt nói \\"tôi 25 tuổi\\" nhưng tiếng Anh không được bỏ \\"am\\", và không dùng \\"have\\".","\\"in + tháng\\" (in May) và \\"in + thành phố\\" (I live in Hanoi). Chỉ ngày cụ thể mới dùng \\"on\\": on May 5th.","\\"I speak English\\": sau \\"speak\\" đi thẳng tên ngôn ngữ, không thêm giới từ."],"examples":[{"en":"I'm twenty-five years old.","vi":"Tôi hai mươi lăm tuổi."},{"en":"My birthday is in May.","vi":"Sinh nhật tôi vào tháng Năm."},{"en":"I live in Hanoi.","vi":"Tôi sống ở Hà Nội."}],"mistake":{"wrong":"I have 25 years old.","right":"I'm 25 years old.","why":"Dịch từ \\"tôi có 25 tuổi\\" là sai. Tiếng Anh dùng \\"be\\" (am/is/are) để nói tuổi."},"lessons":[{"id":"ch22-l11","title":"IN"},{"id":"ch01-l01","title":"Thì hiện tại đơn"}]},{"stage":"food-drink-ordering","title":"Can I have / I would like: gọi món lịch sự","points":["\\"Can I have + món\\" và \\"I would like + món\\" đều dùng để gọi món. \\"I would like\\" lịch sự hơn một chút. Thêm \\"please\\" cho nhẹ nhàng.","Sau \\"Can I\\" là động từ nguyên mẫu, không có \\"to\\": \\"Can I have\\", không phải \\"Can I to have\\".","Món đếm được thì dùng \\"a/an\\": a coffee, a sandwich. Món không đếm được thì dùng \\"some\\": some water, some rice.","\\"Do you have + món?\\" dùng để hỏi quán có món đó không."],"examples":[{"en":"Can I have a coffee, please?","vi":"Cho tôi một ly cà phê nhé?"},{"en":"I would like some water, please.","vi":"Làm ơn cho tôi ít nước."},{"en":"Do you have vegetarian dishes?","vi":"Quán có món chay không?"}],"mistake":{"wrong":"Can I to have a coffee?","right":"Can I have a coffee, please?","why":"Sau \\"can\\" dùng động từ nguyên mẫu không \\"to\\"."},"lessons":[{"id":"ch20-l16","title":"WOULD LIKE"},{"id":"ch12-l01","title":"Some/ any"},{"id":"ch24-l01","title":"Mạo từ bất định"}]},{"stage":"food-likes","title":"Hiện tại đơn: I don't like, I often eat","points":["Dùng thì hiện tại đơn để nói sở thích và thói quen: \\"I often eat eggs for breakfast\\".","Phủ định: \\"I don't + động từ nguyên mẫu\\". Không nói \\"I not like\\" và không thêm gì sau \\"don't\\".","Từ chỉ tần suất như \\"often\\", \\"always\\" đứng trước động từ thường: \\"I often eat\\".","\\"I can cook + món\\": sau \\"can\\" luôn là động từ nguyên mẫu, không thêm -s hay -ing."],"examples":[{"en":"My favorite food is pho.","vi":"Món ăn yêu thích của tôi là phở."},{"en":"I don't like spicy food.","vi":"Tôi không thích đồ ăn cay."},{"en":"I often eat eggs for breakfast.","vi":"Tôi thường ăn trứng vào bữa sáng."}],"mistake":{"wrong":"I not like fish.","right":"I don't like fish.","why":"Phủ định với động từ thường cần trợ động từ \\"do not\\" (don't), không chỉ thêm \\"not\\"."},"lessons":[{"id":"ch01-l01","title":"Thì hiện tại đơn"},{"id":"ch18-l10","title":"Trạng từ chỉ sự tần suất"}]},{"stage":"shopping-prices","title":"How much is...? It is too...: hỏi giá","points":["\\"How much is + món?\\" hỏi giá một món (số ít): How much is this shirt? Nhiều món thì dùng \\"are\\": How much are these shoes?","Đừng quên \\"is/are\\" sau \\"How much\\". Tiếng Việt nói \\"cái áo này bao nhiêu\\" nhưng tiếng Anh cần động từ.","\\"too + tính từ\\" nghĩa là \\"quá\\" và thường mang ý chê: too expensive (quá đắt), too big (quá rộng).","\\"I will take it\\" nghĩa là \\"Tôi lấy cái này\\", dùng khi bạn đã quyết định mua."],"examples":[{"en":"How much is this shirt?","vi":"Cái áo này giá bao nhiêu?"},{"en":"It is too expensive.","vi":"Cái này đắt quá."},{"en":"I will take it.","vi":"Tôi lấy cái này."}],"mistake":{"wrong":"How much this shirt?","right":"How much is this shirt?","why":"Câu hỏi tiếng Anh cần động từ to be: How much + is/are + chủ ngữ."},"lessons":[{"id":"ch06-l02","title":"TOO"},{"id":"ch28-l06","title":"Câu hỏi Wh-"}]},{"stage":"directions-places","title":"Where is...? Is there...? hỏi đường","points":["\\"Where is + nơi?\\" hỏi vị trí. Động từ \\"is\\" đứng trước chủ ngữ: \\"Where is the bank?\\", không phải \\"Where the bank is?\\".","\\"Is there + a/an + nơi + near here?\\" hỏi xem gần đây có nơi đó không. Nơi đếm được ở số ít thì cần \\"a/an\\".","\\"How do I get to + nơi?\\" hỏi cách đi đến một nơi. Nhớ có \\"to\\" ở cuối.","\\"It's + vị trí\\" để trả lời, ví dụ: It's next to the bank."],"examples":[{"en":"Where is the bus station?","vi":"Bến xe buýt ở đâu?"},{"en":"Is there a pharmacy near here?","vi":"Gần đây có hiệu thuốc không?"},{"en":"How do I get to the airport?","vi":"Tôi đến sân bay bằng cách nào?"}],"mistake":{"wrong":"Where the bank is?","right":"Where is the bank?","why":"Trong câu hỏi, \\"is\\" phải đứng trước chủ ngữ, không để sau như câu kể."},"lessons":[{"id":"ch28-l06","title":"Câu hỏi Wh-"},{"id":"ch28-l05","title":"Câu hỏi Yes - No"}]},{"stage":"transport","title":"by + phương tiện, It takes + thời gian","points":["\\"by + phương tiện\\" không có \\"a/the\\": by bus, by motorbike, by taxi. Đi bộ thì nói \\"on foot\\".","Khi chỉ một chuyến cụ thể thì dùng \\"take the + phương tiện\\": You can take the bus.","\\"It takes + thời gian + to get there\\" nói về thời gian di chuyển: It takes twenty minutes.","\\"Does this bus go...?\\": đã có \\"does\\" thì động từ trở về nguyên mẫu \\"go\\", không thêm -es."],"examples":[{"en":"I go to work by motorbike.","vi":"Tôi đi làm bằng xe máy."},{"en":"It takes twenty minutes to get there.","vi":"Đến đó mất hai mươi phút."},{"en":"Does this bus go to the airport?","vi":"Xe buýt này có đi sân bay không?"}],"mistake":{"wrong":"Does this bus goes to the airport?","right":"Does this bus go to the airport?","why":"Sau \\"does\\" động từ ở nguyên mẫu, không thêm -s/-es."},"lessons":[{"id":"ch22-l13","title":"BY"},{"id":"ch01-l01","title":"Thì hiện tại đơn"}]},{"stage":"travel-tickets","title":"Two tickets to..., What time does... leave?","points":["\\"Two tickets to + nơi, please\\": số lượng từ hai trở lên thì danh từ thêm -s (tickets). \\"to\\" chỉ nơi đến.","\\"What time does + chủ ngữ + leave?\\" hỏi giờ khởi hành. Đã có \\"does\\" thì \\"leave\\" không thêm -s.","\\"Is this the right + danh từ?\\" dùng để hỏi xác nhận mình lên đúng xe, đúng quầy, đúng sân ga.","\\"Please\\" ở cuối câu giúp lời yêu cầu lịch sự hơn."],"examples":[{"en":"Two tickets to Da Nang, please.","vi":"Cho tôi hai vé đi Đà Nẵng."},{"en":"What time does the train leave?","vi":"Mấy giờ tàu chạy?"},{"en":"Is this the right platform?","vi":"Đây có phải đúng sân ga không?"}],"mistake":{"wrong":"What time the train leaves?","right":"What time does the train leave?","why":"Câu hỏi cần trợ động từ \\"does\\" sau \\"What time\\", và động từ chính trở về nguyên mẫu."},"lessons":[{"id":"ch28-l06","title":"Câu hỏi Wh-"},{"id":"ch15-l15","title":"Hầu hết các danh từ số nhiều thường thêm s ở cuối."}]},{"stage":"time-dates","title":"at, on, in với giờ và ngày","points":["Dùng \\"at\\" với giờ cụ thể: at 8 o'clock, at half past nine.","Dùng \\"on\\" với thứ và ngày: on Saturday, on May 5th. Dùng \\"in\\" với tháng và năm: in May, in 2025.","\\"It's + giờ\\" để nói bây giờ là mấy giờ: It's half past three now.","\\"The class starts\\" có -s vì \\"the class\\" là ngôi thứ ba số ít (giống he/she/it)."],"examples":[{"en":"It's half past three now.","vi":"Bây giờ là ba giờ rưỡi."},{"en":"The class starts at 8 o'clock.","vi":"Lớp học bắt đầu lúc 8 giờ."},{"en":"I'm free on Saturday.","vi":"Tôi rảnh vào thứ Bảy."}],"mistake":{"wrong":"I'm free in Saturday.","right":"I'm free on Saturday.","why":"Thứ trong tuần và ngày cụ thể đi với \\"on\\", không dùng \\"in\\"."},"lessons":[{"id":"ch22-l07","title":"Giới từ chỉ thời gian"},{"id":"ch22-l10","title":"AT"},{"id":"ch22-l12","title":"ON"}]},{"stage":"weather","title":"It's + tính từ: nói về thời tiết","points":["Nói về thời tiết luôn bắt đầu bằng \\"It's\\": It's hot, It's rainy. Tiếng Việt nói \\"hôm nay nóng\\" nhưng tiếng Anh không được bỏ \\"It's\\".","\\"weather\\" không đếm được nên không có \\"a\\": I don't like cold weather.","\\"Take an umbrella with you\\" là câu mệnh lệnh: bắt đầu bằng động từ, không cần chủ ngữ.","\\"It rains a lot in + nơi/mùa\\": động từ \\"rains\\" có -s vì chủ ngữ là \\"it\\"."],"examples":[{"en":"It's sunny today.","vi":"Hôm nay trời nắng."},{"en":"I don't like cold weather.","vi":"Tôi không thích thời tiết lạnh."},{"en":"Take an umbrella with you.","vi":"Mang theo một cái ô nhé."}],"mistake":{"wrong":"Today hot.","right":"It's hot today.","why":"Câu tiếng Anh cần chủ ngữ và động từ be: dùng \\"It's\\" khi nói về thời tiết."},"lessons":[{"id":"ch30-l09","title":"Câu mệnh lệnh"},{"id":"ch01-l01","title":"Thì hiện tại đơn"}]},{"stage":"daily-routine","title":"Hiện tại đơn: thói quen hằng ngày","points":["Thói quen lặp lại hằng ngày dùng thì hiện tại đơn: I get up at six. I drink coffee every day.","\\"at + giờ\\" cho giờ cụ thể. \\"every day\\" thường đứng cuối câu.","Với I/you/we/they thì động từ giữ nguyên. Với he/she/it phải thêm -s/-es: she gets up, he goes.","Không dùng \\"am/is/are\\" trước động từ thường: nói \\"I get up\\", không nói \\"I am get up\\"."],"examples":[{"en":"I get up at six.","vi":"Tôi thức dậy lúc sáu giờ."},{"en":"I walk to school every day.","vi":"Tôi đi bộ đến trường mỗi ngày."},{"en":"She gets up at six.","vi":"Cô ấy thức dậy lúc sáu giờ."}],"mistake":{"wrong":"She get up at six.","right":"She gets up at six.","why":"Chủ ngữ he/she/it ở hiện tại đơn thì động từ phải thêm -s/-es."},"lessons":[{"id":"ch01-l01","title":"Thì hiện tại đơn"}]},{"stage":"health-body","title":"My ___ hurts / I have a pain in my ___","points":["Nói chỗ đau bằng my + bộ phận cơ thể: My head hurts. Luôn có my, không nói 'the head'.","Động từ hurts có -s khi chỗ đau chỉ có một (head, back). Chỗ đau số nhiều thì không có -s: My legs hurt.","Nói triệu chứng bằng I have + a/an + tên bệnh: I have a headache, I have a fever, I have a cold.","I need + thứ bạn cần: I need water, I need a doctor."],"examples":[{"en":"My stomach hurts.","vi":"Bụng tôi đau."},{"en":"I have a pain in my back.","vi":"Tôi bị đau ở lưng."},{"en":"I have a fever today.","vi":"Hôm nay tôi bị sốt."}],"mistake":{"wrong":"My legs hurts.","right":"My legs hurt.","why":"Legs là số nhiều nên động từ hurt không thêm -s. Chỉ thêm -s khi chủ ngữ là một cái (My leg hurts)."},"lessons":[{"id":"ch01-l01","title":"Thì hiện tại đơn"},{"id":"ch15-l25","title":"Sự tương hợp giữa chủ ngữ và động từ"}]},{"stage":"feelings","title":"am / is / are + tính từ chỉ cảm xúc","points":["Cảm xúc là tính từ (tired, happy, sad), đứng sau am/is/are: I am tired. Không bỏ am/is/are được.","very (rất) đứng trước tính từ: I am very happy. Hỏi lý do: Why are you sad?","Trả lời bằng because + một câu đầy đủ: I am happy because my friend is here.","afraid of + danh từ hoặc V-ing: I am afraid of dogs, I am afraid of flying."],"examples":[{"en":"I am very tired today.","vi":"Hôm nay tôi rất mệt."},{"en":"Why are you sad?","vi":"Sao bạn buồn vậy?"},{"en":"I am afraid of dogs.","vi":"Tôi sợ chó."}],"mistake":{"wrong":"I very tired today.","right":"I am very tired today.","why":"Tiếng Việt nói 'tôi rất mệt' không cần động từ, nhưng tiếng Anh bắt buộc có am/is/are."},"lessons":[{"id":"ch01-l01","title":"Thì hiện tại đơn"},{"id":"ch07-l02","title":"Mệnh đề trạng ngữ chỉ lý do"}]},{"stage":"emergency-help","title":"Câu nhờ vả: Please call... / Can you help me...?","points":["Câu ra lệnh lịch sự bắt đầu bằng động từ, thêm please: Please call the police!","lost là quá khứ của lose. Đồ đã mất rồi thì dùng lost: I lost my passport.","Can you help me + động từ nguyên mẫu? Ví dụ: Can you help me find my bag?","There is + a/an + danh từ số ít báo có gì ở đây: There is a fire here! Nhiều thứ thì There are."],"examples":[{"en":"Please call the police!","vi":"Làm ơn gọi cảnh sát!"},{"en":"I lost my passport.","vi":"Tôi làm mất hộ chiếu rồi."},{"en":"Can you help me find my bag?","vi":"Bạn giúp tôi tìm cái túi được không?"}],"mistake":{"wrong":"I lose my wallet.","right":"I lost my wallet.","why":"Việc mất đã xảy ra rồi nên phải dùng quá khứ lost. Lose chỉ dùng cho việc đang hoặc sẽ mất."},"lessons":[{"id":"ch01-l05","title":"Thì quá khứ đơn"},{"id":"ch28-l03","title":"Câu mệnh lệnh và câu yêu cầu"}]},{"stage":"home-things","title":"There is ___ / Where is ___?","points":["Muốn nói 'có cái gì ở đâu', mở đầu bằng There is + a/an + danh từ số ít: There is a lamp in my room.","Có nhiều cái thì dùng There are + danh từ số nhiều: There are two chairs in my room.","Where is + the + đồ vật hỏi vị trí: Where is the bathroom? Thêm Excuse me cho lịch sự.","Please turn on + đồ vật để nhờ bật đèn, quạt, máy lạnh. Tắt thì dùng turn off."],"examples":[{"en":"There is a TV in my room.","vi":"Trong phòng tôi có một cái ti vi."},{"en":"Excuse me, where is the bathroom?","vi":"Xin lỗi, nhà vệ sinh ở đâu ạ?"},{"en":"Please turn on the air conditioner.","vi":"Làm ơn bật máy lạnh giúp."}],"mistake":{"wrong":"In my room has a desk.","right":"There is a desk in my room.","why":"Tiếng Việt nói 'trong phòng có...', nhưng tiếng Anh không dùng has ở đây mà dùng There is."},"lessons":[{"id":"ch28-l06","title":"Câu hỏi Wh-"},{"id":"ch22-l06","title":"Giới từ chỉ nơi chốn"}]},{"stage":"clothes-colors","title":"want to + động từ; tính từ đứng trước danh từ","points":["Sau want phải có to rồi mới đến động từ: I want to buy a jacket. Không nói 'I want buy'.","Tính từ màu đứng trước danh từ, ngược với tiếng Việt: a blue shirt (không phải 'a shirt blue').","Do you have this in + màu hoặc cỡ? Ở đây in nghĩa là 'với màu, cỡ đó': in black, in size M.","I'm wearing (am + V-ing) nói bạn đang mặc gì hôm nay: I'm wearing a white shirt."],"examples":[{"en":"I want to buy a new jacket.","vi":"Tôi muốn mua một cái áo khoác mới."},{"en":"Do you have this in black?","vi":"Cái này có màu đen không ạ?"},{"en":"I'm wearing a white shirt today.","vi":"Hôm nay tôi mặc áo sơ mi trắng."}],"mistake":{"wrong":"I want buy a shirt blue.","right":"I want to buy a blue shirt.","why":"Cần có to sau want, và tính từ màu phải đứng trước danh từ (khác tiếng Việt)."},"lessons":[{"id":"ch01-l02","title":"Thì hiện tại tiếp diễn"},{"id":"ch20-l10","title":"Cách dùng động từ nguyên thể"},{"id":"ch17-l07","title":"Bổ nghĩa cho danh từ"}]},{"stage":"hobbies-free-time","title":"I like + V-ing; play + môn thể thao","points":["Sau I like có thể là danh từ hoặc động từ thêm -ing: I like music, I like cooking.","Với môn thể thao, play đi thẳng với tên môn, không có the: I play football on weekends.","In my free time, I + động từ nguyên mẫu: In my free time, I read books.","Let's + động từ nguyên mẫu để rủ người khác: Let's watch a movie. Không thêm to sau Let's."],"examples":[{"en":"I like cooking.","vi":"Tôi thích nấu ăn."},{"en":"I play badminton on weekends.","vi":"Cuối tuần tôi chơi cầu lông."},{"en":"Let's watch a movie.","vi":"Mình xem phim đi."}],"mistake":{"wrong":"I play the football on weekends.","right":"I play football on weekends.","why":"Tên môn thể thao không dùng the. Chỉ nhạc cụ mới dùng the: play the guitar."},"lessons":[{"id":"ch24-l21","title":"sports"},{"id":"ch20-l11","title":"Cách dùng của danh động từ"}]},{"stage":"jobs-work","title":"work as / work in / works","points":["work as + nghề, và nghề phải có a/an: I work as a teacher, I work as an engineer.","work in + nơi hoặc ngành: I work in a bank, I work in a hospital.","Chủ ngữ là he/she/it hoặc một người (my sister, my father) thì động từ thêm -s: My sister works in a hospital.","start work at + giờ: I start work at 8 o'clock."],"examples":[{"en":"I work as a nurse.","vi":"Tôi làm y tá."},{"en":"My sister works in a hospital.","vi":"Chị gái tôi làm việc ở bệnh viện."},{"en":"I start work at eight o'clock.","vi":"Tôi bắt đầu làm việc lúc 8 giờ."}],"mistake":{"wrong":"My mother work in a hospital.","right":"My mother works in a hospital.","why":"My mother là ngôi thứ ba số ít (như she), nên động từ phải thêm -s. Tiếng Việt không có quy tắc này."},"lessons":[{"id":"ch01-l01","title":"Thì hiện tại đơn"},{"id":"ch24-l01","title":"Mạo từ bất định"},{"id":"ch22-l10","title":"AT"}]},{"stage":"school-study","title":"go to school + thời gian; Can I borrow...?","points":["study + môn học, không có a/the: I study English at school.","go to school không có the. Thêm cách đi hoặc thời gian phía sau: by bus, by bike, every day.","Can I borrow + đồ vật của người kia? Ví dụ: Can I borrow your pen?","borrow là mình đi mượn (chủ ngữ là I). Nhờ người khác cho mượn thì dùng lend: Can you lend me your pen?"],"examples":[{"en":"I study math at school.","vi":"Tôi học toán ở trường."},{"en":"I go to school by bike.","vi":"Tôi đi học bằng xe đạp."},{"en":"Can I borrow your pen?","vi":"Mình mượn cây bút của bạn được không?"}],"mistake":{"wrong":"Can you borrow me your pen?","right":"Can I borrow your pen?","why":"Borrow là mình mượn nên chủ ngữ là I. Muốn người kia cho mượn thì dùng: Can you lend me...?"},"lessons":[{"id":"ch22-l13","title":"BY"},{"id":"ch01-l01","title":"Thì hiện tại đơn"}]},{"stage":"phone-internet","title":"your/my + danh từ; use ... to + động từ","points":["your, my đứng ngay trước danh từ: Can I use your charger? What is your Wi-Fi password?","has no + danh từ nghĩa là 'không có': My phone has no signal, My phone has no battery.","I use my phone to + động từ nguyên mẫu để nói dùng điện thoại làm gì: I use my phone to take photos.","Hỏi thông tin của người khác bằng What is your + danh từ: What is your phone number?"],"examples":[{"en":"Can I use your charger?","vi":"Cho mình dùng sạc của bạn được không?"},{"en":"What is your Wi-Fi password?","vi":"Mật khẩu Wi-Fi của bạn là gì?"},{"en":"I use my phone to learn English.","vi":"Tôi dùng điện thoại để học tiếng Anh."}],"mistake":{"wrong":"I use my phone for take photos.","right":"I use my phone to take photos.","why":"Chỉ mục đích thì dùng to + động từ. Sau for phải là danh từ hoặc V-ing, không phải động từ nguyên mẫu."},"lessons":[{"id":"ch05-l01","title":"Cụm từ chỉ mục đích"}]},{"stage":"plans-invitations","title":"Let's + V; Do you want to + V?","points":["Let's + động từ nguyên mẫu để rủ ai đó làm gì: Let's go to the cinema. Đáp lại: Good idea! hoặc Sure!","Do you want to + động từ + with me? Câu hỏi dùng Do, và sau want phải có to.","go to + nơi chốn: go to the park. Riêng home thì không có to: Let's go home.","Let's meet at + địa điểm hoặc giờ: Let's meet at the café, Let's meet at six."],"examples":[{"en":"Let's go to the cinema.","vi":"Mình đi xem phim đi."},{"en":"Do you want to have lunch with me?","vi":"Bạn muốn ăn trưa với mình không?"},{"en":"Let's meet at the café at six.","vi":"Mình gặp nhau ở quán cà phê lúc sáu giờ nhé."}],"mistake":{"wrong":"Let's go to home.","right":"Let's go home.","why":"Home ở đây là trạng từ chỉ nơi chốn, nên không cần to. Tiếng Việt 'đi về nhà' dễ làm bạn thêm to."},"lessons":[{"id":"ch22-l14","title":"TO"},{"id":"ch28-l05","title":"Câu hỏi Yes - No"},{"id":"ch22-l10","title":"AT"}]},{"stage":"asking-for-help-repeating","title":"don't understand, Can you...?, What does ___ mean?","points":["I don't understand + từ hoặc cụm từ: I don't understand this word. Sau don't, động từ giữ nguyên.","Can you + động từ nguyên mẫu, please? để nhờ lịch sự: Can you repeat that, please?","What does ___ mean? Có does rồi nên mean không thêm -s.","How do you spell + từ? để hỏi cách đánh vần: How do you spell 'receipt'?"],"examples":[{"en":"Sorry, I don't understand this word.","vi":"Xin lỗi, tôi không hiểu từ này."},{"en":"Can you speak slowly, please?","vi":"Bạn nói chậm lại giúp tôi được không?"},{"en":"What does 'delay' mean?","vi":"'Delay' nghĩa là gì?"}],"mistake":{"wrong":"What does this word means?","right":"What does this word mean?","why":"Does đã mang -s rồi, nên động từ chính mean phải giữ nguyên, không thêm -s nữa."},"lessons":[{"id":"ch28-l06","title":"Câu hỏi Wh-"},{"id":"ch01-l01","title":"Thì hiện tại đơn"}]},{"stage":"hotel-accommodation","title":"I'd like to + V; What time is ___?","points":["I'd like to + động từ nguyên mẫu (I'd like to book a room) lịch sự hơn I want to. I'd like còn đi với danh từ: I'd like a room.","I have a reservation for + thời gian hoặc tên: I have a reservation for two nights.","What time is + sự kiện? hỏi giờ: What time is breakfast? What time is check-out?","Đồ bị hỏng: The + thiết bị + is not working. Nhiều thiết bị thì dùng are not working."],"examples":[{"en":"I have a reservation for two nights.","vi":"Tôi đã đặt phòng hai đêm."},{"en":"I'd like to book a double room.","vi":"Tôi muốn đặt một phòng đôi."},{"en":"The air conditioner is not working.","vi":"Máy lạnh không hoạt động."}],"mistake":{"wrong":"I'd like book a room.","right":"I'd like to book a room.","why":"Sau I'd like phải có to trước động từ, giống như sau want."},"lessons":[{"id":"ch20-l16","title":"WOULD LIKE"},{"id":"ch28-l06","title":"Câu hỏi Wh-"}]}]`),a=JSON.parse(`[{"stage":"a2-past-weekend","title":"Thì quá khứ đơn: kể chuyện đã xảy ra","points":["Chuyện đã xong rồi thì dùng động từ ở quá khứ: went, stayed, met. Các từ như last weekend, yesterday, on Saturday cho biết đó là quá khứ.","Nhiều động từ quen thuộc đổi dạng bất quy tắc: go thành went, meet thành met, have thành had. Cần học thuộc.","Động từ quá khứ không đổi theo chủ ngữ: I went, she went, they went đều giống nhau.","Câu phủ định dùng didn't + động từ nguyên mẫu: I didn't go. Sau didn't không thêm -ed hay đổi dạng nữa."],"examples":[{"en":"Last weekend, I went to my parents' house.","vi":"Cuối tuần trước, tôi về nhà bố mẹ."},{"en":"I met my old classmate on Saturday.","vi":"Thứ Bảy tôi gặp một người bạn học cũ."},{"en":"I didn't go out because I was tired.","vi":"Tôi không đi chơi vì tôi mệt."}],"mistake":{"wrong":"Last weekend I go to my hometown.","right":"Last weekend I went to my hometown.","why":"Động từ tiếng Việt không đổi theo thời gian, nhưng tiếng Anh phải đổi: go thành went."},"lessons":[{"id":"ch01-l05","title":"Thì quá khứ đơn"}]},{"stage":"a2-past-trips","title":"Quá khứ đơn khi kể về chuyến đi","points":["Chuyến đi đã kết thúc thì kể bằng quá khứ đơn: traveled, stayed, took. Last summer, two years ago là dấu hiệu quen thuộc.","Dùng for + khoảng thời gian để nói ở bao lâu: for three days, for a week. Không dùng for trước một mốc như last summer.","Take a photo của take là bất quy tắc: take thành took. Sau of là thứ bạn chụp: a lot of photos of the beach.","Muốn so sánh với điều mình nghĩ trước đó, dùng better than I expected (tốt hơn tôi tưởng)."],"examples":[{"en":"We traveled to Da Lat last summer.","vi":"Mùa hè năm ngoái chúng tôi đi Đà Lạt."},{"en":"We stayed in a small hotel for three days.","vi":"Chúng tôi ở một khách sạn nhỏ ba ngày."},{"en":"The food was better than I expected.","vi":"Đồ ăn ngon hơn tôi tưởng."}],"mistake":{"wrong":"We stay in Hue three days last month.","right":"We stayed in Hue for three days last month.","why":"Cần quá khứ (stayed) vì chuyến đi đã xong, và cần for trước khoảng thời gian (three days)."},"lessons":[{"id":"ch01-l05","title":"Thì quá khứ đơn"},{"id":"ch19-l03","title":"So sánh hơn"}]},{"stage":"a2-future-plans","title":"Be going to, will và câu điều kiện về tương lai","points":["Be going to + động từ dùng cho kế hoạch đã dự định từ trước: I'm going to visit my aunt next month.","Will dùng khi quyết định ngay lúc nói hoặc đoán, thường đi với I think: I think I'll stay home this weekend.","Hope to + động từ nguyên mẫu nói về mong muốn lâu dài: I hope to travel to Japan someday.","If + hiện tại, will + động từ: If it rains tomorrow, I will stay home. Sau if dùng hiện tại, không dùng will."],"examples":[{"en":"I'm going to start a new course next month.","vi":"Tháng sau tôi sẽ bắt đầu một khóa học mới."},{"en":"I think I'll watch a movie this weekend.","vi":"Tôi nghĩ cuối tuần này tôi sẽ xem phim."},{"en":"If it rains tomorrow, I will cancel the picnic.","vi":"Nếu mai trời mưa, tôi sẽ hủy buổi dã ngoại."}],"mistake":{"wrong":"If it will rain tomorrow, I will stay home.","right":"If it rains tomorrow, I will stay home.","why":"Sau if dùng hiện tại đơn dù nói chuyện tương lai. Chỉ vế chính mới dùng will."},"lessons":[{"id":"ch01-l09","title":"Thì tương lai đơn"},{"id":"ch01-l10","title":"Tương lai gần"},{"id":"ch03-l01","title":"Ba loại câu điều kiện"}]},{"stage":"a2-work-intro","title":"Hiện tại hoàn thành với for: làm việc được bao lâu","points":["I've worked here for + khoảng thời gian: việc bắt đầu trong quá khứ và vẫn đang tiếp diễn đến giờ. I've là viết tắt của I have.","For đi với khoảng thời gian (for two years). Since đi với mốc bắt đầu (since 2022).","Khi nói công việc cũ đã kết thúc, dùng quá khứ đơn: Before this job, I worked as a driver.","Mô tả nhiệm vụ: My job is to + động từ nguyên mẫu. Our team takes care of + danh từ (take care of: lo, phụ trách)."],"examples":[{"en":"I've worked here for three years.","vi":"Tôi làm ở đây được ba năm rồi."},{"en":"Before this job, I worked as a waiter.","vi":"Trước công việc này, tôi làm phục vụ bàn."},{"en":"My job is to answer customer questions.","vi":"Việc của tôi là trả lời câu hỏi của khách hàng."}],"mistake":{"wrong":"I work here for three years.","right":"I've worked here for three years.","why":"Việc kéo dài từ quá khứ đến nay thì dùng have + quá khứ phân từ (worked), không dùng hiện tại đơn."},"lessons":[{"id":"ch01-l03","title":"Thì hiện tại hoàn thành"},{"id":"ch01-l05","title":"Thì quá khứ đơn"}]},{"stage":"a2-work-schedule","title":"Have to và too ... to: việc phải làm, quá bận","points":["Have to + động từ nguyên mẫu nghĩa là phải làm vì công việc hay quy định: I have to finish this by Friday. By + mốc nghĩa là chậm nhất lúc đó.","Giải thích lý do bằng because + một câu đầy đủ: I'll be late because the traffic is bad.","Take + thời gian + off là nghỉ phép: I'm taking Friday off. Dùng hiện tại tiếp diễn cho lịch đã sắp xếp.","Too + tính từ + to + động từ nghĩa là quá ... nên không thể: I'm too busy to talk."],"examples":[{"en":"I have to finish this report by five o'clock.","vi":"Tôi phải làm xong báo cáo này trước năm giờ."},{"en":"I'll be late because I have a meeting.","vi":"Tôi sẽ đến muộn vì có một cuộc họp."},{"en":"I'm too busy to have lunch today.","vi":"Hôm nay tôi bận quá nên không ăn trưa được."}],"mistake":{"wrong":"I'll be late because traffic jam.","right":"I'll be late because there is a traffic jam.","why":"Sau because cần một câu có chủ ngữ và động từ. Dùng because of nếu chỉ có danh từ."},"lessons":[{"id":"ch20-l20","title":"HAVE TO"},{"id":"ch06-l02","title":"TOO"},{"id":"ch07-l02","title":"Mệnh đề trạng ngữ chỉ lý do"}]},{"stage":"a2-work-requests","title":"Could you, can you: nhờ vả lịch sự","points":["Could you + động từ nguyên mẫu là cách nhờ lịch sự, dùng với đồng nghiệp hoặc cấp trên. Can you cũng được nhưng thân mật hơn.","Muốn xin phép làm gì, hỏi Do you mind if I + hiện tại: Do you mind if I open the window? Trả lời No, go ahead nghĩa là không sao, cứ làm.","Muốn đề nghị giúp ai, hỏi Do you want me to + động từ nguyên mẫu: Do you want me to call him?","Thêm please hoặc for me để lời nhờ nhẹ nhàng hơn."],"examples":[{"en":"Could you check this email for me?","vi":"Bạn xem giúp tôi email này được không?"},{"en":"Do you mind if I open the window?","vi":"Bạn có phiền nếu tôi mở cửa sổ không?"},{"en":"Do you want me to book the meeting room?","vi":"Bạn có muốn tôi đặt phòng họp không?"}],"mistake":{"wrong":"Could you to help me?","right":"Could you help me?","why":"Sau could, can không dùng to. Động từ đi ngay sau, ở dạng nguyên mẫu."},"lessons":[{"id":"ch28-l03","title":"Câu mệnh lệnh và câu yêu cầu"},{"id":"ch20-l17","title":"COULD/MAY/MIGHT"}]},{"stage":"a2-phone-calls","title":"Nói chuyện qua điện thoại lịch sự","points":["Could I speak to + tên, please? là cách xin gặp ai trên điện thoại. Could lịch sự hơn Can.","I'm calling about + danh từ để nói lý do gọi: I'm calling about the invoice.","Nhờ người khác nhắn lại: ask him to + động từ nguyên mẫu. Could you ask him to call me back?","Không nghe rõ thì nói Sorry, could you speak more slowly, please? hoặc could you repeat that, please?"],"examples":[{"en":"Could I speak to Mr. Lee, please?","vi":"Cho tôi nói chuyện với anh Lee được không ạ?"},{"en":"I'm calling about the meeting on Monday.","vi":"Tôi gọi về cuộc họp hôm thứ Hai."},{"en":"Could you ask him to call me back?","vi":"Bạn nhờ anh ấy gọi lại cho tôi được không?"}],"mistake":{"wrong":"Could you ask him call me back?","right":"Could you ask him to call me back?","why":"Sau ask + người phải có to + động từ: ask him to call."},"lessons":[{"id":"ch28-l03","title":"Câu mệnh lệnh và câu yêu cầu"},{"id":"ch20-l17","title":"COULD/MAY/MIGHT"}]},{"stage":"a2-emails-messages","title":"Cách mở và kết email thông dụng","points":["I'm writing to + động từ nguyên mẫu nêu mục đích email: I'm writing to ask about the schedule.","Please find + danh từ + attached nghĩa là xin xem file đính kèm. Câu này dùng trong email công việc.","Sau giới từ for, động từ thêm -ing: Thank you very much for your help, hoặc for helping me.","Let me know if you need + danh từ: nếu cần gì xin báo tôi biết. Sau if dùng hiện tại, không dùng will."],"examples":[{"en":"I'm writing to confirm our meeting on Friday.","vi":"Tôi viết email này để xác nhận cuộc họp hôm thứ Sáu."},{"en":"Please find the report attached.","vi":"Xin xem báo cáo đính kèm."},{"en":"Thank you very much for sending the file.","vi":"Cảm ơn bạn rất nhiều vì đã gửi file."}],"mistake":{"wrong":"Thank you for help me.","right":"Thank you for helping me.","why":"Sau giới từ for dùng danh từ hoặc động từ thêm -ing, không dùng động từ nguyên mẫu."},"lessons":[{"id":"ch20-l11","title":"Cách dùng của danh động từ"},{"id":"ch05-l01","title":"Cụm từ chỉ mục đích"}]},{"stage":"a2-workplace-problems","title":"Kể sự cố: quá khứ đơn và can't","points":["Sự cố đã xảy ra thì dùng quá khứ đơn kèm mốc thời gian: stopped working this morning, deleted by mistake.","Stop working nghĩa là ngừng hoạt động. Dùng cho máy móc: My printer stopped working. Còn working là dạng -ing đi sau stop.","Can't find nói việc đang không tìm thấy ngay lúc này: I can't find the file. Đây là hiện tại, không phải quá khứ.","Need help with + danh từ để xin giúp đỡ: I need help with the printer. By mistake nghĩa là do nhầm."],"examples":[{"en":"My laptop stopped working this morning.","vi":"Sáng nay máy tính xách tay của tôi bị hỏng."},{"en":"I can't find the invoice in the system.","vi":"Tôi không tìm thấy hóa đơn trong hệ thống."},{"en":"I deleted the file by mistake.","vi":"Tôi xóa nhầm file đó."}],"mistake":{"wrong":"My computer stop working this morning.","right":"My computer stopped working this morning.","why":"Chuyện xảy ra sáng nay là quá khứ, nên stop phải thành stopped (thêm -ed)."},"lessons":[{"id":"ch01-l05","title":"Thì quá khứ đơn"},{"id":"ch20-l11","title":"Cách dùng của danh động từ"}]},{"stage":"a2-doctor-health","title":"Hiện tại hoàn thành: bị bao lâu rồi","points":["I've had + triệu chứng + for + thời gian nói bạn bị từ quá khứ đến giờ: I've had a headache for two days.","Không nói I have a headache for two days. Khi có for + khoảng thời gian, dùng have had.","Should I + động từ nguyên mẫu là hỏi lời khuyên của bác sĩ: Should I take a day off?","It hurts when I + hiện tại để mô tả lúc nào bị đau: It hurts when I swallow. Need to see + bác sĩ nghĩa là cần đi khám."],"examples":[{"en":"I've had a sore throat for two days.","vi":"Tôi bị đau họng hai ngày rồi."},{"en":"I need to see a doctor today.","vi":"Hôm nay tôi cần đi khám bác sĩ."},{"en":"It hurts when I walk.","vi":"Tôi đau mỗi khi đi bộ."}],"mistake":{"wrong":"I have a cough since two days.","right":"I've had a cough for two days.","why":"Dùng have had và for với khoảng thời gian. Since chỉ dùng với mốc, như since Monday."},"lessons":[{"id":"ch01-l03","title":"Thì hiện tại hoàn thành"},{"id":"ch20-l18","title":"SHOULD"}]},{"stage":"a2-pharmacy","title":"Hỏi thuốc: should, make me và anything for","points":["Do you have anything for + bệnh? là câu hỏi quen thuộc ở hiệu thuốc. For ở đây nghĩa là để chữa: anything for a cough.","How often should I take + thuốc? hỏi uống bao lâu một lần. Should + động từ nguyên mẫu là hỏi lời khuyên.","Is it safe to take this with + thuốc hoặc đồ ăn? Sau with là danh từ: with food, with other medicine.","Will this medicine make me + tính từ? hỏi tác dụng phụ: make me sleepy (làm tôi buồn ngủ)."],"examples":[{"en":"Do you have anything for a sore throat?","vi":"Chị có thuốc nào cho đau họng không?"},{"en":"How often should I take this medicine?","vi":"Tôi nên uống thuốc này bao lâu một lần?"},{"en":"Will this medicine make me sleepy?","vi":"Thuốc này có làm tôi buồn ngủ không?"}],"mistake":{"wrong":"How often I should take this?","right":"How often should I take this?","why":"Câu hỏi đảo trợ động từ lên trước chủ ngữ: should I, không phải I should."},"lessons":[{"id":"ch20-l18","title":"SHOULD"},{"id":"ch28-l05","title":"Câu hỏi Yes - No"}]},{"stage":"a2-bank-post","title":"I'd like to và need to: nói điều mình muốn","points":["I'd like to + động từ nguyên mẫu là cách nói muốn làm gì một cách lịch sự. I'd là viết tắt của I would.","I'd like to open an account, I'd like to send a package. Cách này nhẹ nhàng hơn I want to.","I need to + động từ nguyên mẫu nói điều cần làm: I need to withdraw some money. Withdraw là rút tiền.","Is there a fee for + danh từ hoặc V-ing? Sau for dùng danh từ: a fee for sending money."],"examples":[{"en":"I'd like to open a savings account today.","vi":"Hôm nay tôi muốn mở một tài khoản tiết kiệm."},{"en":"I need to withdraw some money today.","vi":"Hôm nay tôi cần rút ít tiền."},{"en":"Is there a fee for sending money abroad?","vi":"Gửi tiền ra nước ngoài có mất phí không?"}],"mistake":{"wrong":"I want open an account.","right":"I'd like to open an account.","why":"Sau want hoặc would like phải có to + động từ. I'd like to lịch sự hơn I want to."},"lessons":[{"id":"ch20-l16","title":"WOULD LIKE"}]},{"stage":"a2-restaurant-requests","title":"Yêu cầu lịch sự: Could I have ... without ...?","points":["Could I / Could we / Could you + động từ nguyên mẫu là cách xin hoặc nhờ lịch sự. Thêm please ở cuối câu thì càng nhẹ nhàng.","Sau without dùng danh từ hoặc V-ing, không dùng động từ nguyên mẫu: without onions, without adding sugar.","Is there ... in it? hỏi xem món có thành phần nào đó không. Dùng any khi hỏi chung: Is there any milk in it?","a little less + tính từ nghĩa là bớt đi một chút: a little less spicy (bớt cay), a little less sweet (bớt ngọt)."],"examples":[{"en":"Could I have this without onions?","vi":"Cho tôi món này không hành được không?"},{"en":"Is there any peanut in it?","vi":"Trong món này có đậu phộng không?"},{"en":"Could you make it a little less spicy?","vi":"Bạn làm món này bớt cay một chút được không?"}],"mistake":{"wrong":"Could I have this without put onions?","right":"Could I have this without onions?","why":"Sau without phải là danh từ hoặc V-ing, không để động từ trần."},"lessons":[{"id":"ch28-l03","title":"Câu mệnh lệnh và câu yêu cầu"},{"id":"ch12-l03","title":"ANY"}]},{"stage":"a2-shopping-compare","title":"So sánh hơn và so sánh bằng khi mua sắm","points":["Tính từ ngắn thêm -er trước than: cheaper than, bigger than. Tính từ dài dùng more: more expensive than, more comfortable than.","as ... as là bằng nhau. not as ... as là kém hơn: It is not as expensive as the other one nghĩa là cái kia đắt hơn.","Ở câu hỏi Which one is ...?, nếu chọn trong nhiều thứ thì dùng dạng cao nhất: the cheapest, the best, the most useful.","Do you have anything cheaper? Đặt tính từ so sánh ngay sau anything để hỏi có món nào rẻ hơn không."],"examples":[{"en":"This one is cheaper than that one.","vi":"Cái này rẻ hơn cái kia."},{"en":"It is not as expensive as the other one.","vi":"Cái này không đắt bằng cái còn lại."},{"en":"Which one do you think is the best?","vi":"Bạn nghĩ cái nào tốt nhất?"}],"mistake":{"wrong":"This one is more cheaper than that one.","right":"This one is cheaper than that one.","why":"Đã có -er thì không thêm more nữa. Chỉ chọn một trong hai cách."},"lessons":[{"id":"ch19-l01","title":"So sánh bằng"},{"id":"ch19-l02","title":"So sánh không bằng"},{"id":"ch19-l03","title":"So sánh hơn"}]},{"stage":"a2-returns-complaints","title":"Nói về lỗi sản phẩm: doesn't work, was broken","points":["Hiện tại phủ định: doesn't + động từ nguyên mẫu, không thêm -s: It doesn't work properly. Với they dùng don't.","Khi nói đã mua lúc nào, dùng quá khứ đơn với mốc thời gian: I bought it yesterday, I bought it last week.","was / were + tính từ hoặc quá khứ phân từ mô tả tình trạng lúc mở hộp: It was broken, It was damaged, It was dirty.","Could I get a refund / a replacement for this? Dùng get hoặc have để xin hoàn tiền hoặc đổi hàng."],"examples":[{"en":"It doesn't work properly.","vi":"Nó không hoạt động bình thường."},{"en":"I bought it yesterday.","vi":"Tôi mới mua nó hôm qua."},{"en":"It was broken when I opened it.","vi":"Nó bị hỏng khi tôi mở hộp."}],"mistake":{"wrong":"It doesn't works properly.","right":"It doesn't work properly.","why":"Sau doesn't động từ phải ở dạng nguyên mẫu, không thêm -s."},"lessons":[{"id":"ch01-l05","title":"Thì quá khứ đơn"},{"id":"ch01-l01","title":"Thì hiện tại đơn"}]},{"stage":"a2-travel-booking","title":"Đặt phòng: I'd like to book, Does the price include?","points":["I'd like to + động từ là cách nói lịch sự của I want to: I'd like to book a room. I'd like = I would like.","for + số đêm hoặc số người: for two nights, for three people. Ngày cụ thể thì dùng on hoặc from ... to.","Is there a room available tonight? available nghĩa là còn trống, còn dùng được. Hỏi chung thì dùng Is there ...?","Câu hỏi với do: Does + chủ ngữ số ít + động từ nguyên mẫu. Does the price include breakfast? Không thêm -s vào include."],"examples":[{"en":"I'd like to book a room for two nights.","vi":"Tôi muốn đặt một phòng cho hai đêm."},{"en":"Can I change my booking to Friday?","vi":"Tôi đổi lịch đặt sang thứ Sáu được không?"},{"en":"Does the price include breakfast?","vi":"Giá này có bao gồm bữa sáng không?"}],"mistake":{"wrong":"Does the price includes breakfast?","right":"Does the price include breakfast?","why":"Đã có Does đứng đầu câu thì động từ chính trở về dạng nguyên mẫu."},"lessons":[{"id":"ch20-l16","title":"WOULD LIKE"},{"id":"ch28-l05","title":"Câu hỏi Yes - No"}]},{"stage":"a2-airport-hotel","title":"Câu hỏi gián tiếp: Could you tell me where ... is?","points":["Sau Could you tell me ... đặt câu hỏi vào trong câu và đổi về thứ tự câu thường: chủ ngữ rồi mới đến động từ. where the gate is, không phải where is the gate.","Câu hỏi gián tiếp nghe lịch sự hơn Where is the gate? và không cần trợ động từ do / does.","Câu hỏi trực tiếp với What time vẫn dùng trợ động từ: What time do I need to check in?","Could you send ... to my room? là mẫu nhờ dịch vụ khách sạn: send a towel, send some water, send a taxi."],"examples":[{"en":"Could you tell me where the gate is?","vi":"Bạn cho tôi biết cổng lên máy bay ở đâu được không?"},{"en":"What time do I need to check in?","vi":"Tôi cần làm thủ tục lúc mấy giờ?"},{"en":"Could you send some towels to my room?","vi":"Bạn gửi vài chiếc khăn tắm lên phòng tôi được không?"}],"mistake":{"wrong":"Could you tell me where is the gate?","right":"Could you tell me where the gate is?","why":"Trong câu hỏi gián tiếp giữ thứ tự câu khẳng định: chủ ngữ trước, động từ sau."},"lessons":[{"id":"ch10-l02","title":"Mệnh đề danh từ làm tân ngữ trong câu"},{"id":"ch28-l06","title":"Câu hỏi Wh-"}]},{"stage":"a2-detailed-directions","title":"Chỉ đường: câu mệnh lệnh và giới từ vị trí","points":["Chỉ đường dùng câu mệnh lệnh: bắt đầu bằng động từ nguyên mẫu, không có chủ ngữ. Turn left, Go straight, Walk past the bank.","at chỉ một điểm: Turn left at the traffic lights. past là đi ngang qua: Go past the bank. opposite là đối diện: It's opposite the park.","Dùng and then để nối bước tiếp theo: Go past the bank and then turn right.","until + mệnh đề: Walk straight until you see the station. Sau until dùng hiện tại đơn, không dùng will."],"examples":[{"en":"Turn left at the traffic lights.","vi":"Rẽ trái ở chỗ đèn giao thông."},{"en":"Go past the bank and then turn right.","vi":"Đi qua ngân hàng rồi rẽ phải."},{"en":"Walk straight until you see the station.","vi":"Đi thẳng cho đến khi bạn thấy nhà ga."}],"mistake":{"wrong":"Walk straight until you will see the station.","right":"Walk straight until you see the station.","why":"Sau until nói về tương lai vẫn dùng hiện tại đơn, không thêm will."},"lessons":[{"id":"ch22-l06","title":"Giới từ chỉ nơi chốn"},{"id":"ch30-l09","title":"Câu mệnh lệnh"}]},{"stage":"a2-opinions","title":"Nói ý kiến: I think we should, I don't think we can","points":["I think we should + động từ nguyên mẫu dùng để đề xuất nhẹ nhàng. should nghĩa là nên, luôn theo sau bởi động từ nguyên mẫu.","I agree with you about + danh từ. Nói đồng ý với ai thì dùng with, không nói agree to you hay am agree.","In my opinion, ... là cách mở đầu khi nói ý kiến riêng. too + tính từ nghĩa là quá mức: too expensive (đắt quá).","Muốn nói không nghĩ là được, đưa not vào think: I don't think we can ..., không nói I think we can't ..."],"examples":[{"en":"I think we should take a taxi.","vi":"Tôi nghĩ chúng ta nên đi taxi."},{"en":"In my opinion, this hotel is too expensive.","vi":"Theo tôi, khách sạn này đắt quá."},{"en":"I don't think we can finish today.","vi":"Tôi không nghĩ chúng ta có thể xong trong hôm nay."}],"mistake":{"wrong":"I think we can't finish today.","right":"I don't think we can finish today.","why":"Với think, người bản xứ đặt phủ định ở think: I don't think ..."},"lessons":[{"id":"ch20-l18","title":"SHOULD"},{"id":"ch06-l02","title":"TOO"}]},{"stage":"a2-likes-reasons","title":"Thích và lý do: because, prefer, enjoy, would rather","points":["because + mệnh đề đầy đủ (có chủ ngữ và động từ): I like this place because it's quiet. Không để because đứng trước danh từ đơn lẻ.","enjoy + V-ing: I enjoy swimming. prefer A to B: cả A và B đều là danh từ hoặc V-ing: I prefer walking to driving.","would rather + động từ nguyên mẫu (không có to) than + động từ nguyên mẫu: I'd rather go out than stay at home.","I'd rather là viết tắt của I would rather. Dùng khi nói điều mình muốn hơn một lựa chọn khác."],"examples":[{"en":"I like this place because it's quiet.","vi":"Tôi thích chỗ này vì nó yên tĩnh."},{"en":"I prefer walking to driving.","vi":"Tôi thích đi bộ hơn lái xe."},{"en":"I'd rather go out than stay at home.","vi":"Tôi thà ra ngoài còn hơn ở nhà."}],"mistake":{"wrong":"I enjoy to walk in the park.","right":"I enjoy walking in the park.","why":"Sau enjoy dùng V-ing, không dùng to + động từ."},"lessons":[{"id":"ch20-l15","title":"WOULD RATHER"},{"id":"ch20-l11","title":"Cách dùng của danh động từ"},{"id":"ch07-l02","title":"Mệnh đề trạng ngữ chỉ lý do"}]},{"stage":"a2-describing","title":"Miêu tả: tính từ đứng trước danh từ, không thêm -s","points":["Tính từ đứng trước danh từ: long hair, a kind person, tall buildings. Tiếng Việt để tính từ sau (tóc dài) nhưng tiếng Anh thì ngược lại.","Tính từ không thay đổi theo số nhiều: many tall buildings, không phải many talls buildings. Chỉ danh từ mới thêm -s.","Miêu tả đặc điểm cơ thể dùng have / has: She has long hair, He has blue eyes. Miêu tả tính cách dùng be: He is a very kind person.","So sánh hai nơi: My new house is bigger than my old one. one thay cho danh từ đã nhắc, tránh lặp lại house."],"examples":[{"en":"She has long black hair.","vi":"Cô ấy có mái tóc đen dài."},{"en":"There are many tall buildings in my city.","vi":"Thành phố tôi có nhiều tòa nhà cao."},{"en":"My new house is bigger than my old one.","vi":"Nhà mới của tôi to hơn nhà cũ."}],"mistake":{"wrong":"She has hair long.","right":"She has long hair.","why":"Tiếng Anh đặt tính từ trước danh từ, khác với tiếng Việt."},"lessons":[{"id":"ch17-l07","title":"Bổ nghĩa cho danh từ"},{"id":"ch17-l11","title":"Trật tự từ của tính từ"},{"id":"ch19-l03","title":"So sánh hơn"}]},{"stage":"a2-invitations","title":"Mời, từ chối, gợi ý: Would you like to, How about","points":["Would you like to + động từ nguyên mẫu là cách mời lịch sự: Would you like to join us? Trả lời: Yes, I'd love to.","Từ chối lịch sự: Sorry, I can't + động từ, rồi nói lý do ngắn: Sorry, I can't come tonight. I have to work.","How about + V-ing hoặc danh từ để gợi ý: How about going to the cinema? How about Saturday?","Thank you for inviting me to + danh từ. Sau giới từ for dùng V-ing: Thank you for inviting me."],"examples":[{"en":"Would you like to have dinner with us?","vi":"Bạn có muốn ăn tối với chúng tôi không?"},{"en":"Sorry, I can't come tonight.","vi":"Xin lỗi, tối nay tôi không đến được."},{"en":"How about going to the cinema on Saturday?","vi":"Thứ Bảy đi xem phim thì sao?"}],"mistake":{"wrong":"How about go to the cinema?","right":"How about going to the cinema?","why":"Sau How about dùng V-ing hoặc danh từ, không dùng động từ nguyên mẫu."},"lessons":[{"id":"ch20-l16","title":"WOULD LIKE"},{"id":"ch20-l11","title":"Cách dùng của danh động từ"}]},{"stage":"a2-experiences","title":"Kinh nghiệm: have + quá khứ phân từ và quá khứ đơn","points":["Have you ever + quá khứ phân từ? hỏi về trải nghiệm trong đời, không nói rõ khi nào. Trả lời: Yes, I have. hoặc No, I've never ...","I've never + quá khứ phân từ nghĩa là chưa từng. I've been to ... twice: đã từng đến nơi đó hai lần (rồi đã về).","Khi có mốc thời gian cụ thể (last year, in 2020, yesterday) thì chuyển sang quá khứ đơn: Last year, I visited Da Nang.","Quá khứ phân từ của động từ bất quy tắc phải học riêng: go, went, gone; see, saw, seen; eat, ate, eaten."],"examples":[{"en":"Have you ever tried Korean food?","vi":"Bạn đã bao giờ thử đồ ăn Hàn Quốc chưa?"},{"en":"I've never ridden a horse before.","vi":"Trước giờ tôi chưa từng cưỡi ngựa."},{"en":"I've been to Da Nang twice.","vi":"Tôi đã đến Đà Nẵng hai lần."}],"mistake":{"wrong":"I have been to Da Lat last year.","right":"I went to Da Lat last year.","why":"Có mốc thời gian đã qua (last year) thì dùng quá khứ đơn, không dùng hiện tại hoàn thành."},"lessons":[{"id":"ch01-l03","title":"Thì hiện tại hoàn thành"},{"id":"ch01-l05","title":"Thì quá khứ đơn"}]},{"stage":"a2-home-neighbors","title":"Nhà ở và hàng xóm: nhờ vả và hỏi thông tin","points":["There's a problem with + danh từ để báo vấn đề: There's a problem with the heater. Số nhiều thì dùng There are problems with ...","Could you please + động từ nguyên mẫu (không có to) để nhờ lịch sự: Could you please turn down the music?","I'm looking for + danh từ dùng hiện tại tiếp diễn vì đang tìm ngay lúc này: I'm looking for a flat near here.","Does the rent include + danh từ? hỏi tiền thuê đã gồm gì chưa: Does the rent include electricity? Động từ include không thêm -s."],"examples":[{"en":"There's a problem with the water heater.","vi":"Máy nước nóng có vấn đề."},{"en":"Could you please turn down the music?","vi":"Bạn làm ơn vặn nhỏ nhạc lại được không?"},{"en":"Does the rent include electricity?","vi":"Tiền thuê nhà có bao gồm tiền điện không?"}],"mistake":{"wrong":"Could you please to turn down the music?","right":"Could you please turn down the music?","why":"Sau Could you (please) dùng động từ nguyên mẫu không có to."},"lessons":[{"id":"ch28-l03","title":"Câu mệnh lệnh và câu yêu cầu"},{"id":"ch01-l02","title":"Thì hiện tại tiếp diễn"}]}]`),g=JSON.parse(`[{"stage":"b1-past-stories","title":"Quá khứ tiếp diễn + quá khứ đơn: kể chuyện","points":["Việc đang diễn ra dùng was/were + động từ thêm -ing: I was walking home.","Việc xen vào giữa chừng dùng quá khứ đơn: ... when the rain started.","While đi với việc kéo dài (was/were + -ing). When thường đi với việc ngắn, xảy ra bất ngờ.","Việc xảy ra trước lúc nhận ra dùng had + quá khứ phân từ: I had left my keys at home."],"examples":[{"en":"I was cooking dinner when the power went out.","vi":"Tôi đang nấu bữa tối thì mất điện."},{"en":"While I was waiting for the bus, my phone died.","vi":"Trong lúc tôi đang đợi xe buýt thì điện thoại hết pin."},{"en":"Suddenly I realized I had left my wallet at home.","vi":"Bỗng nhiên tôi nhận ra mình đã để quên ví ở nhà."}],"mistake":{"wrong":"I was cook when he called.","right":"I was cooking when he called.","why":"Tiếng Việt không đổi dạng động từ, nhưng sau was/were phải dùng động từ thêm -ing."},"lessons":[{"id":"ch01-l05","title":"Thì quá khứ đơn"},{"id":"ch01-l06","title":"Thì quá khứ tiếp diễn"},{"id":"ch01-l07","title":"Thì quá khứ hoàn thành/ Tiền quá khứ"}]},{"stage":"b1-used-to","title":"Used to và be/get used to: hai nghĩa khác nhau","points":["Used to + động từ nguyên mẫu: thói quen cũ, bây giờ không còn. I used to play football.","Câu phủ định và câu hỏi bỏ d: I didn't use to like fish.","Be used to + danh từ hoặc -ing nghĩa là quen với: I'm not used to getting up early.","Get used to + danh từ hoặc -ing nói về quá trình đang quen dần."],"examples":[{"en":"I used to play football every day as a kid.","vi":"Hồi nhỏ ngày nào tôi cũng chơi bóng đá."},{"en":"I'm not used to getting up early yet.","vi":"Tôi vẫn chưa quen với việc dậy sớm."},{"en":"I'm slowly getting used to the weather here.","vi":"Tôi đang dần quen với thời tiết ở đây."}],"mistake":{"wrong":"I'm not used to wake up early.","right":"I'm not used to waking up early.","why":"Be used to (quen với) đi với danh từ hoặc -ing. Used to + nguyên mẫu mới là thói quen cũ."},"lessons":[{"id":"ch20-l14","title":"USED TO - BE"}]},{"stage":"b1-life-changes","title":"Hiện tại hoàn thành với for và since","points":["Việc bắt đầu trong quá khứ và còn liên quan đến bây giờ dùng have/has + quá khứ phân từ.","For + khoảng thời gian (for a few months). Since + mốc thời gian (since 2020, since March).","Việc vẫn đang tiếp tục có thể dùng have been + -ing: I've been learning English.","Have just + quá khứ phân từ nói việc vừa mới xảy ra."],"examples":[{"en":"I've been learning English for a few months.","vi":"Tôi học tiếng Anh được vài tháng rồi."},{"en":"I've lived here since 2020.","vi":"Tôi sống ở đây từ năm 2020."},{"en":"Life has changed a lot since I moved to Hanoi.","vi":"Cuộc sống đã thay đổi rất nhiều từ khi tôi chuyển ra Hà Nội."}],"mistake":{"wrong":"I live here since 2020.","right":"I have lived here since 2020.","why":"Việc kéo dài từ quá khứ đến nay phải dùng hiện tại hoàn thành, không dùng hiện tại đơn với since."},"lessons":[{"id":"ch01-l03","title":"Thì hiện tại hoàn thành"},{"id":"ch01-l04","title":"Thì hiện tại hoàn thành tiếp diễn"}]},{"stage":"b1-advice","title":"Cho lời khuyên: if I were you, had better, why don't you","points":["If I were you, I'd + động từ nguyên mẫu. Luôn dùng were, kể cả với I.","You'd better + động từ nguyên mẫu (không có to): khuyên mạnh, nếu không làm có thể gặp rắc rối.","Why don't you + động từ nguyên mẫu: lời khuyên thân thiện, nhẹ nhàng.","It might help to + động từ nguyên mẫu: lời khuyên mềm, không ép người nghe."],"examples":[{"en":"If I were you, I'd talk to your boss.","vi":"Nếu tôi là bạn, tôi sẽ nói chuyện với sếp."},{"en":"You'd better leave now, or you'll miss the train.","vi":"Bạn nên đi ngay, không thì sẽ lỡ chuyến tàu."},{"en":"Why don't you try a different approach?","vi":"Sao bạn không thử một cách tiếp cận khác?"}],"mistake":{"wrong":"You'd better to go to the doctor.","right":"You'd better go to the doctor.","why":"Sau had better dùng động từ nguyên mẫu không to."},"lessons":[{"id":"ch03-l01","title":"Ba loại câu điều kiện"},{"id":"ch20-l18","title":"SHOULD"}]},{"stage":"b1-suggestions","title":"Đề xuất: could, shall we, suggest, what if","points":["We could + động từ nguyên mẫu: đưa ra một lựa chọn khác. Instead đứng cuối câu nghĩa là thay vì cách vừa nói.","Shall we + động từ nguyên mẫu: rủ ai cùng làm gì. Shall chỉ dùng với I và we.","I suggest we + động từ nguyên mẫu: hơi trang trọng, hợp khi họp hoặc bàn công việc.","What if we + quá khứ đơn hoặc hiện tại đơn? Dùng để thử một ý mới khi thương lượng."],"examples":[{"en":"We could take the train instead.","vi":"Thay vào đó chúng ta có thể đi tàu."},{"en":"Shall we start at nine?","vi":"Mình bắt đầu lúc chín giờ nhé?"},{"en":"I suggest we ask the manager first.","vi":"Tôi đề nghị chúng ta hỏi quản lý trước."}],"mistake":{"wrong":"I suggest to go by taxi.","right":"I suggest we go by taxi.","why":"Suggest không đi với to + động từ. Dùng suggest + we + động từ, hoặc suggest + -ing."},"lessons":[{"id":"ch20-l17","title":"COULD/MAY/MIGHT"}]},{"stage":"b1-preferences","title":"Would rather + động từ: nói điều bạn thích hơn","points":["I'd rather + động từ nguyên mẫu không to: nói bạn thích làm việc nào hơn.","Phủ định là I'd rather not. Muốn so sánh thì thêm than: I'd rather walk than drive.","It depends on + danh từ: chưa trả lời chắc được vì còn phụ thuộc vào điều khác.","I'd go for + danh từ: tôi sẽ chọn cái đó. I'm more of a ___ person: nói về tính cách, sở thích."],"examples":[{"en":"I'd rather stay at home tonight.","vi":"Tối nay tôi muốn ở nhà hơn."},{"en":"It depends on the weather.","vi":"Còn tùy vào thời tiết."},{"en":"I'm more of a coffee person.","vi":"Tôi là kiểu người thích cà phê hơn."}],"mistake":{"wrong":"I'd rather to stay at home.","right":"I'd rather stay at home.","why":"Sau would rather dùng động từ nguyên mẫu không to, giống các động từ khuyết thiếu."},"lessons":[{"id":"ch20-l15","title":"WOULD RATHER"}]},{"stage":"b1-job-interview","title":"Sau giới từ dùng -ing: good at, experience in","points":["Be good at + danh từ hoặc -ing: nói điểm mạnh. I'm good at solving problems.","Have experience in + danh từ chỉ lĩnh vực. Không cần chia thì sau in.","My biggest strength is + danh từ hoặc -ing, rồi nói thêm một ví dụ ngắn cho thuyết phục.","I'd like to + động từ nguyên mẫu: cách nói lịch sự về mong muốn, hợp để trả lời về mục tiêu."],"examples":[{"en":"I'm good at solving problems under pressure.","vi":"Tôi giỏi giải quyết vấn đề khi bị áp lực."},{"en":"I have experience in customer service.","vi":"Tôi có kinh nghiệm trong lĩnh vực chăm sóc khách hàng."},{"en":"In five years, I'd like to lead a small team.","vi":"Trong năm năm tới, tôi muốn dẫn dắt một nhóm nhỏ."}],"mistake":{"wrong":"I'm good at solve problems.","right":"I'm good at solving problems.","why":"Sau giới từ (at, in, about) dùng danh từ hoặc -ing, không dùng động từ nguyên mẫu."},"lessons":[{"id":"ch22-l19","title":"Giới từ theo sau các tính từ"},{"id":"ch20-l16","title":"WOULD LIKE"}]},{"stage":"b1-meetings","title":"Câu lịch sự khi họp: could you, can we, I'd like to","points":["Let's move on to + danh từ: chuyển sang mục tiếp theo. Sau to là danh từ, thường có the.","Could you + động từ nguyên mẫu: lịch sự hơn can you. Clarify nghĩa là làm rõ.","I'd like to add + danh từ: chen ý vào một cách nhã nhặn.","Agree on + danh từ hoặc cụm như who does what: cả nhóm cùng chốt một việc."],"examples":[{"en":"Let's move on to the budget.","vi":"Chúng ta chuyển sang phần ngân sách nhé."},{"en":"Could you clarify what you mean by phase two?","vi":"Bạn có thể làm rõ ý của bạn về giai đoạn hai không?"},{"en":"Can we agree on a deadline today?","vi":"Hôm nay chúng ta chốt hạn chót được không?"}],"mistake":{"wrong":"Could you to clarify this point?","right":"Could you clarify this point?","why":"Sau could/can dùng động từ nguyên mẫu không to."},"lessons":[{"id":"ch20-l16","title":"WOULD LIKE"}]},{"stage":"b1-presentations","title":"Mở bài, chuyển ý và kết bài khi thuyết trình","points":["Today I'll talk about + danh từ hoặc how to + động từ: báo trước chủ đề bằng I'll.","Let me start with + danh từ (a story, a question) để mở đầu.","As you can see, + câu đầy đủ: dùng khi chỉ vào biểu đồ hoặc hình. Nói ở hiện tại hoặc quá khứ đơn.","To sum up, + câu đầy đủ: nhắc lại ý chính ở phần kết, nói ngắn và rõ."],"examples":[{"en":"Today I'll talk about how to save energy at home.","vi":"Hôm nay tôi sẽ nói về cách tiết kiệm điện ở nhà."},{"en":"As you can see, sales went up in March.","vi":"Như các bạn thấy, doanh số đã tăng vào tháng Ba."},{"en":"To sum up, we need more time and a bigger budget.","vi":"Tóm lại, chúng ta cần thêm thời gian và ngân sách lớn hơn."}],"mistake":{"wrong":"Today I'll talk about to reduce waste.","right":"Today I'll talk about how to reduce waste.","why":"Sau about cần danh từ hoặc how to + động từ, không đặt to + động từ ngay sau about."},"lessons":[{"id":"ch01-l09","title":"Thì tương lai đơn"}]},{"stage":"b1-reports-updates","title":"Hiện tại hoàn thành và I'll: báo cáo tiến độ","points":["Have been + -ing: việc bắt đầu trước đây và vẫn đang làm. I've been working on the website.","Have/has + quá khứ phân từ với already: việc đã xong, kết quả còn dùng được bây giờ.","We're running behind on + danh từ: đang trễ so với kế hoạch. Dùng hiện tại tiếp diễn vì tình trạng đang diễn ra.","I'll + động từ nguyên mẫu + by tomorrow: hứa gửi chậm nhất là ngày mai."],"examples":[{"en":"I've been working on the new website since Monday.","vi":"Tôi làm trang web mới từ thứ Hai đến giờ."},{"en":"We've already finished the first draft.","vi":"Chúng tôi đã hoàn thành bản nháp đầu tiên rồi."},{"en":"I'll send you the report by tomorrow.","vi":"Tôi sẽ gửi báo cáo cho bạn chậm nhất là ngày mai."}],"mistake":{"wrong":"We have finish the design.","right":"We have finished the design.","why":"Have/has phải đi với quá khứ phân từ (finished), không dùng động từ nguyên mẫu."},"lessons":[{"id":"ch01-l03","title":"Thì hiện tại hoàn thành"},{"id":"ch01-l04","title":"Thì hiện tại hoàn thành tiếp diễn"},{"id":"ch01-l09","title":"Thì tương lai đơn"}]},{"stage":"b1-deadlines","title":"Xin đổi thời hạn một cách lịch sự","points":["Would it be possible to + động từ nguyên mẫu: cách xin phép rất lịch sự khi muốn đổi kế hoạch.","I'm afraid I can't + động từ nguyên mẫu: báo tin không vui một cách nhẹ nhàng.","By Friday nghĩa là chậm nhất là thứ Sáu. Could we extend + danh từ: xin gia hạn.","I'll do my best to + động từ nguyên mẫu: hứa cố gắng nhưng chưa chắc chắn."],"examples":[{"en":"Would it be possible to move the meeting to Monday?","vi":"Có thể dời cuộc họp sang thứ Hai được không?"},{"en":"I'm afraid I can't finish the report by Friday.","vi":"Tôi e là tôi không thể xong báo cáo trước thứ Sáu."},{"en":"I'll do my best to send it earlier.","vi":"Tôi sẽ cố gắng gửi sớm hơn."}],"mistake":{"wrong":"Would it be possible to extending the deadline?","right":"Would it be possible to extend the deadline?","why":"Sau to trong possible to dùng động từ nguyên mẫu, không thêm -ing."},"lessons":[{"id":"ch20-l17","title":"COULD/MAY/MIGHT"}]},{"stage":"b1-customer-service","title":"Xin lỗi và phàn nàn: sorry for, complain about","points":["I'm sorry for + danh từ hoặc -ing: xin lỗi về điều đã xảy ra. Không dùng nguyên mẫu sau for.","I'd like to complain about + danh từ: phàn nàn nhưng vẫn nhã nhặn.","We'll look into + danh từ: nhân viên hứa sẽ xem xét, điều tra vấn đề.","I understand that + mệnh đề: cho khách thấy bạn thông cảm với họ."],"examples":[{"en":"I'm sorry for the delay.","vi":"Tôi xin lỗi vì sự chậm trễ."},{"en":"I'd like to complain about the slow service.","vi":"Tôi muốn phàn nàn về việc phục vụ chậm."},{"en":"We'll look into the problem right away.","vi":"Chúng tôi sẽ xem xét vấn đề này ngay."}],"mistake":{"wrong":"I'd like to complain for the service.","right":"I'd like to complain about the service.","why":"Phàn nàn về điều gì dùng complain about, không dùng for."},"lessons":[{"id":"ch22-l19","title":"Giới từ theo sau các tính từ"}]},{"stage":"b1-travel-problems","title":"Quá khứ và bị động: missed, was delayed","points":["Chuyện đã xảy ra thì động từ chuyển sang quá khứ: miss thành missed. Tiếng Việt không đổi dạng động từ, nên dễ quên.","Was delayed nghĩa là bị trễ (câu bị động): chủ ngữ là thứ chịu việc trễ, không phải thứ tự làm. Chủ ngữ số nhiều thì dùng were delayed.","Need to + động từ nguyên mẫu nói điều cần làm: I need to rebook. Rebook đi thẳng với danh từ, không thêm giới từ.","What should I do about + danh từ dùng để xin lời khuyên về một rắc rối."],"examples":[{"en":"I missed my flight because of the traffic.","vi":"Tôi lỡ chuyến bay vì kẹt xe."},{"en":"My train was delayed by two hours.","vi":"Chuyến tàu của tôi bị trễ hai tiếng."},{"en":"What should I do about my lost luggage?","vi":"Tôi nên làm gì với hành lý bị thất lạc đây?"}],"mistake":{"wrong":"My flight delayed two hours.","right":"My flight was delayed for two hours.","why":"Chuyến bay bị trễ nên cần bị động: was delayed. Chỉ có delayed thì không đủ."},"lessons":[]},{"stage":"b1-renting-booking","title":"Nhờ và hỏi lịch sự: I'd like, Could you","points":["I'd like to + động từ nguyên mẫu lịch sự hơn I want to. Dùng khi thuê, đặt chỗ hoặc gọi món.","Could you + động từ nguyên mẫu (không có to) là cách nhờ nhẹ nhàng: Could you recommend a hotel?","Is there an extra charge for + danh từ? dùng để hỏi trước về phí thêm. Sau for là danh từ hoặc động từ thêm ing.","Đã đặt từ trước thì dùng quá khứ: I booked a room online."],"examples":[{"en":"I'd like to rent a car for three days.","vi":"Tôi muốn thuê một chiếc xe trong ba ngày."},{"en":"Is there an extra charge for breakfast?","vi":"Bữa sáng có tính thêm phí không?"},{"en":"I booked a double room online.","vi":"Tôi đã đặt một phòng đôi qua mạng."}],"mistake":{"wrong":"Could you to recommend a good restaurant?","right":"Could you recommend a good restaurant?","why":"Sau could (và các động từ khuyết thiếu khác) dùng động từ nguyên mẫu không có to."},"lessons":[{"id":"ch20-l16","title":"WOULD LIKE"},{"id":"ch20-l17","title":"COULD/MAY/MIGHT"}]},{"stage":"b1-tourist-info","title":"Hỏi gợi ý: best way to, worth, take","points":["The best way to + động từ nguyên mẫu hỏi cách tốt nhất để làm gì: What's the best way to get downtown?","Worth + động từ thêm ing nghĩa là đáng để làm: Is it worth visiting the museum? Không dùng to sau worth.","How long does it take to + động từ? hỏi thời gian cần cho việc. Chủ ngữ it đi với does, và take giữ nguyên.","Should definitely + động từ nguyên mẫu là lời gợi ý mạnh. Definitely đứng giữa should và động từ."],"examples":[{"en":"What's the best way to get to the old town?","vi":"Cách tốt nhất để đến khu phố cổ là gì?"},{"en":"Is it worth visiting the night market?","vi":"Chợ đêm có đáng đi không?"},{"en":"You should definitely try the local coffee.","vi":"Bạn nhất định nên thử cà phê địa phương."}],"mistake":{"wrong":"Is it worth to visit this island?","right":"Is it worth visiting this island?","why":"Sau worth luôn dùng động từ thêm ing, không dùng to + động từ."},"lessons":[{"id":"ch20-l18","title":"SHOULD"}]},{"stage":"b1-opinions-reasons","title":"Nêu ý kiến và lý do: To me, That's why","points":["To me, ... mở đầu cho ý kiến cá nhân. Sau đó là một câu đầy đủ, nhớ có động từ is: To me, health is important.","The main problem is / One reason is + cụm danh từ hoặc một câu. Nhớ giữ động từ is, tiếng Việt thường bỏ.","That's why + chủ ngữ + động từ nói kết quả của điều vừa nêu: It's cheap. That's why I like it.","Because chỉ lý do, còn that's why chỉ kết quả. Hai từ này không thay thế cho nhau."],"examples":[{"en":"To me, sleep is really important.","vi":"Với tôi, giấc ngủ rất quan trọng."},{"en":"The main problem is the high price.","vi":"Vấn đề chính là giá quá cao."},{"en":"The bus is always late. That's why I walk to work.","vi":"Xe buýt luôn trễ. Vì thế tôi đi bộ đi làm."}],"mistake":{"wrong":"To me, family really important.","right":"To me, family is really important.","why":"Tiếng Việt không cần động từ be trước tính từ, nhưng tiếng Anh luôn cần is/are/am."},"lessons":[{"id":"ch07-l02","title":"Mệnh đề trạng ngữ chỉ lý do"}]},{"stage":"b1-agree-disagree","title":"Phản đối lịch sự: I see your point, but","points":["Ghi nhận ý người kia trước (I see your point), rồi mới nói but. Cách này nghe mềm hơn nói thẳng I disagree.","I partly agree with + người hoặc ý kiến. Sau with là danh từ, không phải một câu: with you, with Anna.","I'm not sure that's + tính từ hoặc a + danh từ là cách nói không đồng ý nhẹ nhàng.","Isn't it ...? (câu hỏi phủ định) làm lời phản đối nghe như một câu hỏi gợi ý, ít gay gắt hơn."],"examples":[{"en":"I see your point, but it costs too much.","vi":"Tôi hiểu ý bạn, nhưng nó tốn quá nhiều tiền."},{"en":"I partly agree with you.","vi":"Tôi đồng ý với bạn một phần."},{"en":"Maybe, but isn't it a bit dangerous?","vi":"Có thể, nhưng như vậy có hơi nguy hiểm không?"}],"mistake":{"wrong":"I'm agree with you.","right":"I agree with you.","why":"Agree đã là động từ, không cần am/is/are. Tiếng Việt nói \\"tôi đồng ý\\" nên dễ thêm be."},"lessons":[{"id":"ch08-l02","title":"Mệnh đề trạng ngữ chỉ sự nhượng bộ"}]},{"stage":"b1-reporting-speech","title":"Câu gián tiếp: said that, told me to","points":["Kể lại lời người khác thì động từ thường lùi một thì: am thành was, can thành could, will thành would. Đại từ cũng đổi: I thành he/she.","Say không cần người nghe: He said that he was tired. Tell cần người nghe ngay sau: He told me that he was tired.","Told me to + động từ nguyên mẫu kể lại yêu cầu. Phủ định là told me not to.","Kể lại câu hỏi: asked if / wants to know + từ hỏi, rồi chủ ngữ + động từ như câu thường, không dùng do/does."],"examples":[{"en":"He said that he was too busy to come.","vi":"Anh ấy nói rằng anh ấy quá bận nên không đến được."},{"en":"She told me to call her back later.","vi":"Cô ấy bảo tôi gọi lại cho cô ấy sau."},{"en":"They asked me if I was free on Friday.","vi":"Họ hỏi tôi có rảnh vào thứ Sáu không."}],"mistake":{"wrong":"He said me that he was tired.","right":"He told me that he was tired.","why":"Say không đi với người nghe. Muốn có me thì dùng tell: told me."},"lessons":[{"id":"ch28-l01","title":"Thay đổi thì động từ"},{"id":"ch28-l03","title":"Câu mệnh lệnh và câu yêu cầu"},{"id":"ch28-l05","title":"Câu hỏi Yes - No"}]},{"stage":"b1-conditionals","title":"Câu điều kiện: If I have, If I were","points":["Việc có thể xảy ra: If + hiện tại đơn, will + động từ. Vế if không dùng will: If I have time, I'll call you.","Việc không có thật hoặc khó xảy ra: If + quá khứ đơn, would + động từ. Với I/he/she thường dùng were: If I were rich.","Unless nghĩa là if ... not (nếu không). Sau unless dùng hiện tại đơn, không thêm not: Unless it rains, we'll go.","What would you do if + quá khứ đơn? dùng để hỏi một tình huống tưởng tượng."],"examples":[{"en":"If I have time, I'll visit my grandparents.","vi":"Nếu có thời gian, tôi sẽ đi thăm ông bà."},{"en":"If I were rich, I'd travel around the world.","vi":"Nếu giàu, tôi sẽ đi du lịch vòng quanh thế giới."},{"en":"What would you do if you lost your phone?","vi":"Bạn sẽ làm gì nếu bị mất điện thoại?"}],"mistake":{"wrong":"If I will have time, I will call you.","right":"If I have time, I'll call you.","why":"Trong mệnh đề if không dùng will. Tiếng Việt \\"nếu tôi sẽ có\\" khiến dễ thêm will."},"lessons":[{"id":"ch03-l01","title":"Ba loại câu điều kiện"},{"id":"ch03-l02","title":"Dùng UNLESS thay cho IF"}]},{"stage":"b1-health-lifestyle","title":"Khuyên và thói quen: shouldn't, give up","points":["Should / shouldn't + động từ nguyên mẫu (không có to) dùng để khuyên: You shouldn't eat too much sugar.","Give up + danh từ hoặc động từ thêm ing nghĩa là bỏ thói quen. Dùng I've given up (hiện tại hoàn thành) vì kết quả còn đến bây giờ.","Try to + động từ nguyên mẫu là cố gắng làm. Every day đứng cuối câu để nói thói quen.","It's good for you to + động từ nguyên mẫu nói việc có lợi, nghe là lời khuyên nhẹ nhàng."],"examples":[{"en":"I try to walk for thirty minutes every day.","vi":"Tôi cố gắng đi bộ ba mươi phút mỗi ngày."},{"en":"You shouldn't drink too much coffee.","vi":"Bạn không nên uống quá nhiều cà phê."},{"en":"I've given up smoking.","vi":"Tôi đã bỏ thuốc lá."}],"mistake":{"wrong":"You shouldn't to eat too much.","right":"You shouldn't eat too much.","why":"Sau should/shouldn't dùng động từ nguyên mẫu không có to."},"lessons":[{"id":"ch20-l18","title":"SHOULD"},{"id":"ch01-l03","title":"Thì hiện tại hoàn thành"}]},{"stage":"b1-technology","title":"Dạng V-ing: spend time, keeps crashing","points":["Spend time + động từ thêm ing: I spend a lot of time playing games. Hoặc dùng on + danh từ: spend time on my phone.","Without là giới từ, nên sau nó dùng danh từ hoặc động từ thêm ing: I can't live without my phone.","Keep + động từ thêm ing nghĩa là cứ lặp lại mãi: My laptop keeps crashing. Chủ ngữ số ít thì dùng keeps.","It's easy to + động từ nguyên mẫu nói một việc dễ làm. With this app cho biết dùng công cụ nào."],"examples":[{"en":"I spend a lot of time watching videos.","vi":"Tôi dành nhiều thời gian xem video."},{"en":"I can't live without my phone.","vi":"Tôi không thể sống thiếu điện thoại."},{"en":"My laptop keeps crashing.","vi":"Laptop của tôi cứ bị treo hoài."}],"mistake":{"wrong":"My phone keep crash.","right":"My phone keeps crashing.","why":"Chủ ngữ số ít cần keeps, và động từ sau keep phải thêm ing."},"lessons":[]},{"stage":"b1-feelings-reactions","title":"Diễn tả cảm xúc: surprised that, worried about","points":["Tính từ cảm xúc đi với giới từ riêng: worried about, surprised at/by. Sau about dùng danh từ hoặc động từ thêm ing.","Surprised that và can't believe được theo sau bởi một câu đầy đủ (có chủ ngữ và động từ). Chuyện đã xảy ra thì dùng quá khứ.","It makes me + tính từ nghĩa là điều đó khiến tôi cảm thấy thế nào: It makes me happy.","Phân biệt: I'm bored (tôi chán) và it's boring (nó chán). Người cảm thấy dùng -ed, điều gây ra cảm xúc dùng -ing."],"examples":[{"en":"I was surprised that she remembered my name.","vi":"Tôi ngạc nhiên là cô ấy nhớ tên tôi."},{"en":"It always makes me smile.","vi":"Điều đó luôn làm tôi mỉm cười."},{"en":"I'm worried about my exam.","vi":"Tôi lo lắng về kỳ thi của mình."}],"mistake":{"wrong":"I interested in this movie.","right":"I'm interested in this movie.","why":"Interested là tính từ nên cần am/is/are phía trước. Tiếng Việt không cần động từ này."},"lessons":[]},{"stage":"b1-plans-hopes","title":"Dự định và ước: thinking of, planning to, wish","points":["I'm thinking of + động từ thêm ing: mới đang cân nhắc. I'm planning to + động từ nguyên mẫu: kế hoạch đã rõ hơn.","Wish I could + động từ nguyên mẫu nói điều mình muốn nhưng hiện tại chưa làm được. Dùng could, không dùng can.","I'd like to + động từ nguyên mẫu nói điều muốn một cách lịch sự. One day đứng đầu câu cho ước mơ xa.","Thinking of đi với ing vì of là giới từ, còn planning to đi với động từ nguyên mẫu."],"examples":[{"en":"I'm thinking of moving to a new city next year.","vi":"Năm sau tôi đang nghĩ đến chuyện chuyển sang thành phố mới."},{"en":"I'm planning to visit Da Nang this summer.","vi":"Hè này tôi dự định đi Đà Nẵng."},{"en":"I wish I could speak English fluently.","vi":"Ước gì tôi nói tiếng Anh trôi chảy được."}],"mistake":{"wrong":"I wish I can speak English well.","right":"I wish I could speak English well.","why":"Sau wish (ước điều chưa có ở hiện tại) động từ lùi thành quá khứ: can thành could."},"lessons":[{"id":"ch04-l02","title":"Ao ước ở hiện tại"},{"id":"ch20-l16","title":"WOULD LIKE"}]},{"stage":"b1-polite-questions","title":"Hỏi gián tiếp: Do you know if, how much it costs","points":["Hỏi gián tiếp dùng trật tự câu thường: chủ ngữ rồi động từ, không đảo và không dùng do/does. Đúng là how much it costs.","Câu hỏi có/không dùng if hoặc whether: Do you know if the bank is open?","Would you mind + động từ thêm ing nhờ lịch sự. Trả lời Not at all nghĩa là đồng ý.","I was wondering if you could + động từ nguyên mẫu là cách nhờ rất lịch sự, dùng quá khứ để mềm hơn."],"examples":[{"en":"Do you know if the museum is open on Sundays?","vi":"Bạn có biết bảo tàng có mở cửa vào Chủ nhật không?"},{"en":"I was wondering if you could help me with this form.","vi":"Không biết bạn có thể giúp tôi điền mẫu này được không."},{"en":"I'd like to know how much this ticket costs.","vi":"Tôi muốn biết vé này giá bao nhiêu."}],"mistake":{"wrong":"Do you know where is the bank?","right":"Do you know where the bank is?","why":"Trong hỏi gián tiếp giữ trật tự câu thường: where + chủ ngữ + động từ."},"lessons":[{"id":"ch28-l05","title":"Câu hỏi Yes - No"},{"id":"ch28-l06","title":"Câu hỏi Wh-"},{"id":"ch10-l02","title":"Mệnh đề danh từ làm tân ngữ trong câu"}]}]`),s=JSON.parse(`[{"stage":"b2-speculating-past","title":"Đoán về quá khứ: must have, might have, can't have","points":["Modal + have + quá khứ phân từ dùng để đoán chuyện đã xảy ra: must have gone, might have forgotten.","Must have: gần như chắc chắn. Might have hoặc could have: có thể, không chắc. Can't have: chắc chắn là không.","Phủ định của must have là can't have, không phải mustn't have. Mustn't nghĩa là cấm.","Sau have luôn là quá khứ phân từ: gone, been, left, không dùng động từ nguyên mẫu."],"examples":[{"en":"She must have missed the bus.","vi":"Chắc hẳn cô ấy đã lỡ xe buýt."},{"en":"He might have been stuck in traffic.","vi":"Có thể anh ấy đã bị kẹt xe."},{"en":"It can't have been cheap.","vi":"Chắc chắn là không rẻ đâu."}],"mistake":{"wrong":"He mustn't have seen my message.","right":"He can't have seen my message.","why":"Mustn't nghĩa là cấm. Muốn nói chắc chắn đã không xảy ra thì dùng can't have."},"lessons":[]},{"stage":"b2-regrets","title":"Tiếc nuối: wish + had, should have, if only","points":["Tiếc về quá khứ: I wish hoặc If only + had + quá khứ phân từ. Thì lùi một bậc so với sự việc thật.","Should have + quá khứ phân từ: lẽ ra nên làm. Shouldn't have: lẽ ra không nên làm.","If only mạnh hơn I wish và thường đứng một mình như một câu cảm thán.","It would have been better to + động từ nguyên mẫu là cách nói nhẹ nhàng khi nhìn lại."],"examples":[{"en":"I wish I had studied harder.","vi":"Giá mà tôi đã học chăm hơn."},{"en":"We should have left earlier.","vi":"Lẽ ra chúng ta nên đi sớm hơn."},{"en":"If only I hadn't said that.","vi":"Giá như tôi đã không nói điều đó."}],"mistake":{"wrong":"I wish I studied harder at school.","right":"I wish I had studied harder at school.","why":"Tiếc chuyện ở quá khứ thì dùng had cộng quá khứ phân từ. Studied chỉ dùng khi ước về hiện tại."},"lessons":[{"id":"ch04-l03","title":"Ao ước ở quá khứ"},{"id":"ch28-l11","title":"Quá khứ giả định"}]},{"stage":"b2-third-conditional","title":"Điều kiện loại ba và câu điều kiện hỗn hợp","points":["Loại ba nói về quá khứ không có thật: If + had + quá khứ phân từ, would have + quá khứ phân từ.","Không dùng would trong vế if. Viết tắt I'd ở vế if là I had, ở vế sau là I would.","Hỗn hợp: quá khứ dẫn tới hiện tại. If I had taken that job, I would be rich now.","Trang trọng hơn: bỏ if và đảo had lên đầu. Had I known, I would have come."],"examples":[{"en":"If I had known, I would have helped you.","vi":"Nếu tôi biết thì tôi đã giúp bạn rồi."},{"en":"If we had left earlier, we wouldn't be so late now.","vi":"Nếu đi sớm hơn thì giờ chúng ta đã không muộn thế này."},{"en":"Had she asked, I would have explained.","vi":"Nếu cô ấy hỏi, tôi đã giải thích rồi."}],"mistake":{"wrong":"If I would have known, I would have come.","right":"If I had known, I would have come.","why":"Vế if của câu điều kiện loại ba dùng had cộng quá khứ phân từ, không dùng would have."},"lessons":[{"id":"ch03-l01","title":"Ba loại câu điều kiện"},{"id":"ch03-l03","title":"Đảo ngữ trong câu điều kiện"}]},{"stage":"b2-hypotheticals","title":"Giả định: what if, suppose, I'd rather you","points":["What if, suppose, imagine if + thì quá khứ đặt ra một tình huống tưởng tượng ở hiện tại hoặc tương lai.","Câu hỏi đi kèm dùng would: Suppose you won the lottery, what would you do?","I'd rather you + thì quá khứ là nhờ hoặc phản đối lịch sự: I'd rather you didn't smoke here.","Với cùng một người thì dùng động từ nguyên mẫu: I'd rather stay. Khác người mới cần thì quá khứ."],"examples":[{"en":"What if we moved the meeting to Friday?","vi":"Nếu mình dời cuộc họp sang thứ Sáu thì sao?"},{"en":"Suppose you lost your job, what would you do?","vi":"Giả sử bạn mất việc, bạn sẽ làm gì?"},{"en":"I'd rather you called me first.","vi":"Tôi mong bạn gọi cho tôi trước thì hơn."}],"mistake":{"wrong":"I'd rather you don't tell anyone.","right":"I'd rather you didn't tell anyone.","why":"Sau I'd rather you dùng thì quá khứ dù ý vẫn nói về hiện tại."},"lessons":[{"id":"ch09-l17","title":"Mệnh đề sau WOULD RATHER"},{"id":"ch20-l15","title":"WOULD RATHER"},{"id":"ch28-l11","title":"Quá khứ giả định"}]},{"stage":"b2-arguing-a-point","title":"Giữ vững quan điểm: the thing is, my point is","points":["The thing is hoặc The problem is mở đầu lý do chính. Sau đó là một mệnh đề đầy đủ.","What I'm getting at is hoặc My point is giúp kéo cuộc nói chuyện về đúng ý chính của bạn.","Let's not forget that nhắc lại một sự thật để lập luận vững hơn, nghe lịch sự hơn You forget that.","That's exactly why biến lý lẽ của người kia thành lý do ủng hộ bạn."],"examples":[{"en":"The thing is, we don't have the budget.","vi":"Vấn đề là chúng ta không có ngân sách."},{"en":"My point is that time is limited.","vi":"Ý tôi là thời gian có hạn."},{"en":"That's exactly why we need a plan.","vi":"Chính vì vậy mà chúng ta cần một kế hoạch."}],"mistake":{"wrong":"The thing is that, we have no time.","right":"The thing is, we have no time.","why":"Dùng the thing is that không có dấu phẩy, hoặc the thing is có dấu phẩy. Không dùng cả hai."},"lessons":[]},{"stage":"b2-contrasting","title":"Đối lập: whereas, despite, even though","points":["Whereas nối hai ý trái ngược trong cùng một câu, trước nó thường có dấu phẩy.","Despite và in spite of đi với danh từ hoặc động từ thêm ing. Although và even though đi với mệnh đề.","Even though nhấn mạnh hơn although. Không dùng thêm but trong cùng câu.","On the other hand đưa ra mặt còn lại khi so sánh ưu và nhược điểm."],"examples":[{"en":"Despite the delays, we finished on time.","vi":"Dù bị chậm trễ, chúng tôi vẫn xong đúng hạn."},{"en":"Even though it was expensive, I enjoyed it.","vi":"Mặc dù đắt, tôi vẫn thấy thích."},{"en":"I like mornings, whereas she likes evenings.","vi":"Tôi thích buổi sáng, còn cô ấy thích buổi tối."}],"mistake":{"wrong":"Although it was late, but she called back.","right":"Although it was late, she called back.","why":"Tiếng Việt nói Dù... nhưng..., còn tiếng Anh chỉ dùng although hoặc but, không dùng cả hai."},"lessons":[{"id":"ch09-l01","title":"Although his English was good, he wasn’t chosen."},{"id":"ch09-l10","title":"Although Mary was sad, she managed to smile."}]},{"stage":"b2-emphasis","title":"Nhấn mạnh: What I need is, It was... that","points":["Câu chẻ với what đẩy ý chính xuống cuối: What I need is more time.","It was + phần nhấn mạnh + that hoặc who chỉ rõ đúng người, đúng nguyên nhân: It was Linh who found it.","Thêm do, does, did trước động từ nguyên mẫu để khẳng định mạnh: I do care. She did call.","The reason is that hoặc The reason I'm calling is giúp nói lý do rõ ràng ngay từ đầu."],"examples":[{"en":"What I really need is a long holiday.","vi":"Điều tôi thật sự cần là một kỳ nghỉ dài."},{"en":"It was the update that caused the problem.","vi":"Chính bản cập nhật đã gây ra sự cố."},{"en":"I do understand the risk.","vi":"Tôi có hiểu rủi ro thật mà."}],"mistake":{"wrong":"I do cares about it.","right":"I do care about it.","why":"Sau do, does, did nhấn mạnh thì động từ giữ nguyên mẫu, không thêm s hay ed."},"lessons":[{"id":"ch14-l02","title":"Nhấn mạnh trong cách viết"}]},{"stage":"b2-hedging","title":"Nói giảm cho lịch sự: it seems, I'd tend to think","points":["It seems that, it appears that, it looks like làm tin xấu nghe nhẹ hơn và cho thấy bạn chưa chắc chắn.","I'd tend to think, I'd say đưa ý kiến mà vẫn để ngỏ cho người khác bàn thêm.","It might be a good idea to + động từ thay cho you should khi góp ý với cấp trên hoặc khách hàng.","Not entirely, not quite làm lời phản đối mềm hơn: I'm not entirely sure."],"examples":[{"en":"It seems that there's been a mistake.","vi":"Có vẻ như đã có nhầm lẫn."},{"en":"I'd tend to think it's too early.","vi":"Tôi thiên về nghĩ là còn quá sớm."},{"en":"It might be a good idea to check again.","vi":"Có lẽ sẽ tốt nếu mình kiểm tra lại."}],"mistake":{"wrong":"It seems that the server is down, I am sure.","right":"It seems that the server is down.","why":"It seems đã có nghĩa là chưa chắc chắn, thêm I am sure làm câu tự mâu thuẫn."},"lessons":[]},{"stage":"b2-persuading","title":"Thuyết phục khéo: câu hỏi phủ định và worth","points":["Câu hỏi phủ định như Wouldn't it be better to hoặc Isn't it safer to gợi ý nhẹ nhàng mà vẫn có sức nặng.","Worth đi với danh từ hoặc động từ thêm ing: worth the money, worth trying. Không dùng worth to try.","Regret cộng động từ thêm ing nói về việc đã làm: You won't regret trying it.","Nêu lợi ích cụ thể thay vì chỉ nói nó tốt: The great thing about it is it saves time."],"examples":[{"en":"Wouldn't it be better to book in advance?","vi":"Chẳng phải đặt trước sẽ tốt hơn sao?"},{"en":"Trust me, it's worth the extra money.","vi":"Tin tôi đi, bỏ thêm tiền rất đáng đấy."},{"en":"You won't regret coming with us.","vi":"Bạn sẽ không hối hận khi đi cùng chúng tôi đâu."}],"mistake":{"wrong":"This course is worth to try.","right":"This course is worth trying.","why":"Sau worth là động từ thêm ing hoặc danh từ, không dùng to cộng động từ."},"lessons":[]},{"stage":"b2-negotiating","title":"Điều kiện khi thương lượng: provided that, as long as","points":["Provided that, providing, as long as, on condition that đều nghĩa là với điều kiện là, thay cho if.","Sau các từ này dùng thì hiện tại dù nói về tương lai: provided that you pay in advance.","Điều kiện loại một hợp để chốt: If you can lower the price, we'll sign today.","In return hoặc in exchange giúp bạn đưa ra nhượng bộ để đổi lấy điều mình cần."],"examples":[{"en":"We can agree, provided that delivery is on time.","vi":"Chúng tôi có thể đồng ý, với điều kiện giao hàng đúng hạn."},{"en":"As long as the price is right, it's a deal.","vi":"Miễn là giá hợp lý thì chốt nhé."},{"en":"We could offer free delivery in return.","vi":"Đổi lại, chúng tôi có thể miễn phí giao hàng."}],"mistake":{"wrong":"We agree, provided that you will pay in advance.","right":"We agree, provided that you pay in advance.","why":"Giống vế if, sau provided that không dùng will mà dùng thì hiện tại."},"lessons":[{"id":"ch03-l04","title":"Các liên từ khác thay thế IF"},{"id":"ch03-l01","title":"Ba loại câu điều kiện"}]},{"stage":"b2-giving-feedback","title":"Góp ý mềm mỏng và nhận góp ý","points":["Bắt đầu bằng điểm tốt cụ thể: What I really liked was the clear structure.","Nêu điểm cần sửa nhẹ nhàng: One thing you could improve is, hoặc It would be even better if.","Sau It would be even better if dùng thì quá khứ vì đó là điều giả định: if you added a chart.","Feedback và advice là danh từ không đếm được: không nói a feedback hay feedbacks."],"examples":[{"en":"What I really liked was your opening.","vi":"Điều tôi thật sự thích là phần mở đầu của bạn."},{"en":"It would be even better if it were shorter.","vi":"Sẽ còn tốt hơn nữa nếu nó ngắn hơn."},{"en":"Thanks for the feedback, I'll work on that.","vi":"Cảm ơn góp ý nhé, tôi sẽ cải thiện điểm đó."}],"mistake":{"wrong":"Thank you for your feedbacks.","right":"Thank you for your feedback.","why":"Feedback là danh từ không đếm được nên không thêm s. Muốn đếm thì nói a piece of feedback."},"lessons":[]},{"stage":"b2-solving-problems","title":"Xử lý sự cố: giải pháp, tạm thời, phòng ngừa","points":["Đưa giải pháp trước: The quickest fix would be to restart the server.","Cách tạm thời trong lúc chờ: In the meantime, we can handle orders manually.","Phòng ngừa: To prevent this happening again, cộng một kế hoạch cụ thể.","Sau once, as soon as, when nói về tương lai thì dùng hiện tại, không dùng will."],"examples":[{"en":"The quickest fix would be to clear the cache.","vi":"Cách khắc phục nhanh nhất là xóa bộ nhớ đệm."},{"en":"In the meantime, we can use the old version.","vi":"Trong lúc chờ, chúng ta có thể dùng bản cũ."},{"en":"I'll get back to you once it's fixed.","vi":"Tôi sẽ báo lại cho bạn ngay khi lỗi được sửa xong."}],"mistake":{"wrong":"I'll call you once I will finish checking.","right":"I'll call you once I've finished checking.","why":"Vế sau once nói về tương lai nhưng dùng hiện tại hoặc hiện tại hoàn thành, không dùng will."},"lessons":[{"id":"ch02-l02","title":"Sự phối hợp thì trong mệnh đề chính và mệnh đề trạng ng…"}]},{"stage":"b2-running-meetings","title":"Điều phối họp: mở đầu, mời nói, gác lại, chốt","points":["Mở đầu bằng mục tiêu: The aim today is to agree on the budget.","Mời người khác nói: Let's hear from Minh first, hoặc Lan, would you like to add anything?","Gác chủ đề lạc đề: Can we park that for now? Hoặc Let's take that offline.","Kết thúc bằng điều đã chốt: So we've all agreed to, rồi nói ai làm gì."],"examples":[{"en":"The aim today is to plan the launch.","vi":"Mục tiêu hôm nay là lên kế hoạch ra mắt."},{"en":"Can we park the budget issue for now?","vi":"Mình tạm gác vấn đề ngân sách lại nhé?"},{"en":"So we've all agreed to meet again on Friday.","vi":"Vậy là mọi người đã thống nhất họp lại vào thứ Sáu."}],"mistake":{"wrong":"We discussed about the budget.","right":"We discussed the budget.","why":"Discuss là ngoại động từ, theo sau là tân ngữ luôn, không thêm about. Talk about thì có about."},"lessons":[]},{"stage":"b2-formal-emails","title":"Email trang trọng: mở, nhờ, kết","points":["Mở thư: I am writing with regard to, hoặc I am writing to. Thư trang trọng ít viết tắt.","Nhờ lịch sự: I would be grateful if you could, cộng động từ nguyên mẫu.","Kết thư: Please do not hesitate to contact me, rồi I look forward to hearing from you.","Look forward to: to là giới từ nên theo sau là động từ thêm ing hoặc danh từ."],"examples":[{"en":"I am writing with regard to your recent order.","vi":"Tôi viết thư này liên quan đến đơn hàng gần đây của quý vị."},{"en":"I would be grateful if you could confirm by Friday.","vi":"Tôi rất biết ơn nếu quý vị có thể xác nhận trước thứ Sáu."},{"en":"I look forward to hearing from you.","vi":"Tôi rất mong nhận được hồi âm của quý vị."}],"mistake":{"wrong":"I look forward to hear from you.","right":"I look forward to hearing from you.","why":"To trong look forward to là giới từ, nên động từ phía sau phải thêm ing."},"lessons":[]},{"stage":"b2-it-is-said","title":"Bị động tường thuật: It is said that, is thought to","points":["Cách một: It is said, believed, reported that cộng một mệnh đề đầy đủ.","Cách hai: chủ ngữ cộng is said, thought, believed to cộng động từ nguyên mẫu: He is said to be rich.","Việc đang xảy ra dùng to be đang làm. Việc đã xảy ra dùng to have cộng quá khứ phân từ.","Hay gặp trong tin tức khi không muốn hoặc không thể nêu nguồn cụ thể."],"examples":[{"en":"It is said that this place is haunted.","vi":"Người ta nói rằng nơi này có ma."},{"en":"He is thought to be living abroad.","vi":"Nhiều người cho rằng anh ấy đang sống ở nước ngoài."},{"en":"The singer is reported to have left the band.","vi":"Theo báo chí, ca sĩ đó đã rời ban nhạc."}],"mistake":{"wrong":"He is said that he is very rich.","right":"It is said that he is very rich.","why":"Đã dùng that cộng mệnh đề thì chủ ngữ phải là It. Nếu bắt đầu bằng He thì nói He is said to be rich."},"lessons":[{"id":"ch29-l07","title":"Động từ chỉ ý kiến"}]},{"stage":"b2-having-things-done","title":"Thể sai khiến: have hoặc get something done","points":["Have hoặc get cộng đồ vật cộng quá khứ phân từ: nhờ hoặc thuê người khác làm cho mình.","Đồ vật đứng giữa, quá khứ phân từ đứng cuối: I had my hair cut, không nói I cut my hair nếu thợ cắt.","Get thân mật hơn have. Có thể chia ở mọi thì: We're having new windows installed.","Cũng dùng cho chuyện không may xảy ra với mình: I had my wallet stolen."],"examples":[{"en":"I need to get my phone fixed.","vi":"Tôi cần mang điện thoại đi sửa."},{"en":"We're having solar panels installed next week.","vi":"Tuần sau nhà mình sẽ được lắp tấm pin mặt trời."},{"en":"I had my passport stolen.","vi":"Tôi bị mất cắp hộ chiếu."}],"mistake":{"wrong":"I cut my hair yesterday at a new salon.","right":"I had my hair cut yesterday at a new salon.","why":"Người Việt hay nói tôi cắt tóc, nhưng thợ mới là người cắt, nên tiếng Anh dùng had my hair cut."},"lessons":[{"id":"ch29-l05","title":"Thể sai khiến"}]},{"stage":"b2-complaining","title":"Khiếu nại lịch sự mà vẫn rõ ràng","points":["Theo ba bước: nói vấn đề, đưa bằng chứng, rồi nêu điều bạn muốn như refund, replacement hay discount.","Complain about + vấn đề: I'd like to complain about the noise. Không nói complain the noise.","Giữ giọng bình tĩnh, dùng I'm afraid hoặc Could you để lời phàn nàn nghe chuyên nghiệp hơn.","Hỏi lý do bằng Could you explain why, sau why là câu kể bình thường, không đảo ngữ."],"examples":[{"en":"This isn't what I ordered.","vi":"Đây không phải món tôi đã gọi."},{"en":"I'd like a refund for the cancelled flight.","vi":"Tôi muốn được hoàn tiền cho chuyến bay bị hủy."},{"en":"Could you explain why my card was charged twice?","vi":"Bạn có thể giải thích vì sao thẻ của tôi bị trừ tiền hai lần không?"}],"mistake":{"wrong":"I want to complain the room.","right":"I'd like to complain about the room.","why":"Complain cần có about trước điều bạn phàn nàn. I'd like to cũng lịch sự hơn I want to."},"lessons":[{"id":"ch13-l37","title":"to complain about"}]},{"stage":"b2-trouble-abroad","title":"Xử lý sự cố khi ở nước ngoài","points":["Report dùng khi trình báo: I need to report a stolen phone. Nhớ xin police report để làm bảo hiểm.","Miss là lỡ chuyến, lose là làm mất đồ. I missed my flight, I lost my passport.","Cover trong bảo hiểm nghĩa là chi trả. Make a claim là làm hồ sơ đòi bồi thường.","Khi không biết gọi ai, nhờ người khác: Could you put me in touch with the embassy?"],"examples":[{"en":"I need to report a lost passport.","vi":"Tôi cần trình báo việc mất hộ chiếu."},{"en":"Does my insurance cover hospital bills?","vi":"Bảo hiểm của tôi có chi trả viện phí không?"},{"en":"I've missed my connection to Seoul.","vi":"Tôi bị lỡ chuyến bay nối tiếp đi Seoul."}],"mistake":{"wrong":"I lost my flight to Seoul.","right":"I missed my flight to Seoul.","why":"Tiếng Việt nói mất chuyến bay, nhưng tiếng Anh dùng miss. Lose chỉ dùng khi làm mất đồ vật."},"lessons":[]},{"stage":"b2-small-talk","title":"Giữ mạch chuyện khi nói chuyện xã giao","points":["Hỏi câu mở thay vì câu có hoặc không: What made you move here? giúp người kia kể thêm.","Nối chuyện bằng That reminds me of hoặc Speaking of để cuộc trò chuyện chảy tự nhiên.","By the way và Anyway dùng để chuyển chủ đề nhẹ nhàng, không bị đột ngột.","Câu hỏi đuôi như isn't it, don't you mời người kia đồng tình và nói tiếp."],"examples":[{"en":"So, how do you know the host?","vi":"Thế bạn quen chủ nhà thế nào?"},{"en":"Oh really? What made you learn Japanese?","vi":"Ồ thật à? Điều gì khiến bạn học tiếng Nhật?"},{"en":"Great party, isn't it?","vi":"Bữa tiệc vui nhỉ?"}],"mistake":{"wrong":"What made you to choose this job?","right":"What made you choose this job?","why":"Sau make cộng người, động từ để nguyên mẫu không có to."},"lessons":[]},{"stage":"b2-storytelling","title":"Kể chuyện: quá khứ tiếp diễn và quá khứ đơn","points":["Quá khứ tiếp diễn tả bối cảnh, quá khứ đơn là sự việc chen vào: I was cooking when the phone rang.","Dùng All of a sudden, Just then để tạo bất ngờ, In the end hoặc To cut a long story short để kết.","Mở đầu gây tò mò: You'll never guess what happened. Sau what là câu kể, không đảo ngữ.","Trong khi kể, dùng thì quá khứ cho đồng bộ, đừng nhảy qua lại với hiện tại."],"examples":[{"en":"I was just leaving the house when the phone rang.","vi":"Tôi vừa ra khỏi nhà thì điện thoại reo."},{"en":"All of a sudden, the lights went out.","vi":"Đột nhiên, đèn tắt phụt."},{"en":"To cut a long story short, we got lost.","vi":"Nói ngắn gọn thì chúng tôi bị lạc."}],"mistake":{"wrong":"I cooked dinner when the phone was ringing.","right":"I was cooking dinner when the phone rang.","why":"Việc đang diễn ra dài hơn dùng quá khứ tiếp diễn. Việc ngắn chen ngang dùng quá khứ đơn."},"lessons":[{"id":"ch01-l06","title":"Thì quá khứ tiếp diễn"},{"id":"ch01-l05","title":"Thì quá khứ đơn"}]},{"stage":"b2-predicting","title":"Dự đoán: likely, bound to, I doubt, a good chance","points":["Từ chắc đến không chắc: bound to, likely to, there's a good chance, I doubt.","Be likely to và be bound to đi với động từ nguyên mẫu: It's likely to rain.","I doubt mang nghĩa phủ định sẵn, phía sau là câu khẳng định: I doubt he'll come.","I'd be surprised if cộng quá khứ đơn là cách khéo léo nói việc khó xảy ra."],"examples":[{"en":"It's likely to take longer.","vi":"Nhiều khả năng là sẽ mất nhiều thời gian hơn."},{"en":"There's a good chance she'll get the job.","vi":"Rất có thể cô ấy sẽ được nhận vào làm."},{"en":"I doubt they'll agree.","vi":"Tôi không nghĩ là họ sẽ đồng ý."}],"mistake":{"wrong":"I doubt he won't come.","right":"I doubt he'll come.","why":"I doubt đã có nghĩa là tôi nghĩ là không, thêm not sẽ thành phủ định hai lần và sai nghĩa."},"lessons":[]},{"stage":"b2-cause-effect","title":"Nói nguyên nhân và hệ quả","points":["Nguyên nhân là danh từ: due to, because of, thanks to. Nguyên nhân là mệnh đề: because, since.","Thanks to dùng cho kết quả tốt. Kết quả xấu thì dùng because of hoặc due to.","Nêu hệ quả: As a result hoặc Therefore ở đầu câu, This has led to cộng danh từ.","Lead to, result in, cause đều đi trực tiếp với danh từ: This led to higher prices."],"examples":[{"en":"This is mainly due to rising costs.","vi":"Việc này chủ yếu là do chi phí tăng."},{"en":"As a result, the project was delayed.","vi":"Vì vậy, dự án bị chậm."},{"en":"Thanks to your help, we finished on time.","vi":"Nhờ có sự giúp đỡ của bạn, chúng tôi đã xong đúng hạn."}],"mistake":{"wrong":"Because of it rained, the match was cancelled.","right":"Because it rained, the match was cancelled.","why":"Because of chỉ đi với danh từ. Trước cả một mệnh đề có chủ ngữ và động từ thì dùng because."},"lessons":[{"id":"ch07-l02","title":"Mệnh đề trạng ngữ chỉ lý do"},{"id":"ch22-l03","title":"Giới từ có thể là một ngữ"},{"id":"ch06-l01","title":"Cụm từ chỉ kết quả"}]},{"stage":"b2-trends","title":"Mô tả số liệu: rise, fall, level off","points":["Động từ: rise, rose, risen; fall, fell, fallen; level off là chững lại; peak là chạm đỉnh.","Trạng từ cho động từ: rose sharply, fell slightly. Tính từ cho danh từ: a sharp rise, a slight fall.","Rise to là tăng lên đến mức nào. Rise by là tăng thêm một lượng bao nhiêu.","Danh từ rise, increase, drop đi với in: a steady rise in prices."],"examples":[{"en":"Sales rose sharply in March.","vi":"Doanh số tăng mạnh vào tháng Ba."},{"en":"The number of users fell slightly to ten thousand.","vi":"Số người dùng giảm nhẹ, xuống còn mười nghìn."},{"en":"There's been a steady rise in online orders.","vi":"Thời gian qua, số đơn hàng trực tuyến tăng đều."}],"mistake":{"wrong":"Sales were increased sharply last year.","right":"Sales increased sharply last year.","why":"Increase, rise, fall ở đây là nội động từ, không dùng bị động. Doanh số tự tăng chứ không bị ai tăng."},"lessons":[{"id":"ch18-l07","title":"Trạng từ chỉ thể cách"}]},{"stage":"b2-declining-politely","title":"Từ chối khéo mà không mất lòng","points":["Cảm ơn hoặc tỏ ra quý lời mời trước: Thanks for asking hoặc I'd love to, rồi mới nói but.","Lý do ngắn và thật là đủ, không cần giải thích dài dòng.","Can I take a rain check là xin dời sang dịp khác, cho thấy bạn vẫn muốn đi.","Trong công việc, I'm afraid và Unfortunately làm lời từ chối mềm và chuyên nghiệp hơn."],"examples":[{"en":"I'd love to, but I'm working that day.","vi":"Mình rất muốn, nhưng hôm đó mình phải làm."},{"en":"Can I take a rain check on dinner?","vi":"Mình hẹn bữa tối hôm khác được không?"},{"en":"I'm afraid I must say no to the offer.","vi":"Tôi e là tôi phải từ chối lời đề nghị này."}],"mistake":{"wrong":"No, I don't want. I'm busy.","right":"I'd love to, but I'm a bit busy.","why":"Từ chối thẳng nghe cộc lốc trong tiếng Anh. Nên tỏ ra quý lời mời trước rồi mới từ chối."},"lessons":[]}]`),l=JSON.parse(`[{"stage":"c1-nuanced-opinions","title":"Nêu ý kiến có sắc thái","points":["As far as I'm concerned và to my mind báo hiệu đây là quan điểm riêng, trang trọng hơn I think.","It strikes me that hoặc it occurs to me that đưa ra một nhận xét vừa nghĩ ra, nghe tinh tế, không áp đặt.","I'd go as far as to say báo trước một nhận định mạnh. Ngược lại, I wouldn't go that far làm ý nhẹ đi.","Không dùng In my opinion và I think trong cùng một câu, vì nghĩa bị lặp."],"examples":[{"en":"As far as I'm concerned, the matter is closed.","vi":"Theo tôi thì chuyện này đã xong."},{"en":"It strikes me that nobody asked the users.","vi":"Tôi chợt nhận ra là chưa ai hỏi người dùng."},{"en":"To my mind, both sides have a point.","vi":"Theo tôi, cả hai bên đều có lý."}],"mistake":{"wrong":"In my opinion, I think it's too expensive.","right":"In my opinion, it's too expensive.","why":"In my opinion đã có nghĩa là tôi nghĩ, thêm I think nữa là lặp ý."},"lessons":[]},{"stage":"c1-conceding","title":"Nhượng bộ rồi phản biện","points":["Granted và admittedly thừa nhận một điểm đúng của người kia trước, rồi but đưa ra lập luận chính.","I take your point, point taken, fair enough cho thấy bạn đã nghe kỹ trước khi phản biện.","Be that as it may, even so, that said đều nghĩa là dù vậy. Be that as it may trang trọng nhất.","Much as I like it là cách nói trang trọng của although I like it."],"examples":[{"en":"Granted, it's expensive, but it's still worth it.","vi":"Đúng là nó đắt, nhưng vẫn đáng."},{"en":"I take your point, but the data says otherwise.","vi":"Tôi ghi nhận ý bạn, nhưng số liệu lại nói khác."},{"en":"Much as I like the idea, it's unrealistic.","vi":"Dù rất thích ý tưởng này, nó không thực tế."}],"mistake":{"wrong":"Even so that, we should try.","right":"Even so, we should try.","why":"Even so đứng một mình như dù vậy. Không thêm that phía sau."},"lessons":[]},{"stage":"c1-inversion","title":"Đảo ngữ nhấn mạnh: never have I, not only","points":["Khi never, rarely, seldom, not only, only when đứng đầu câu, trợ động từ đảo lên trước chủ ngữ.","Câu không có trợ động từ thì mượn do, does, did: Rarely do we get feedback like this.","Với only when, only after, đảo ngữ nằm ở vế sau: Only when it was too late did we realise.","Under no circumstances, on no account rất trang trọng, hay gặp trong quy định và cảnh báo."],"examples":[{"en":"Never have I seen such a mess.","vi":"Chưa bao giờ tôi thấy cảnh bừa bộn như vậy."},{"en":"Not only is it fast, but it's cheap too.","vi":"Nó không chỉ nhanh mà còn rẻ nữa."},{"en":"Only then did I understand the problem.","vi":"Chỉ đến lúc đó tôi mới hiểu vấn đề."}],"mistake":{"wrong":"Never I have seen such a mess.","right":"Never have I seen such a mess.","why":"Never đứng đầu câu thì trợ động từ have phải đứng trước chủ ngữ I."},"lessons":[{"id":"ch18-l18","title":"Phép đảo chủ ngữ và động từ sau các trạng từ"},{"id":"ch03-l03","title":"Đảo ngữ trong câu điều kiện"}]},{"stage":"c1-advanced-conditionals","title":"Điều kiện nâng cao: should you, but for, assuming","points":["Should you need là đảo ngữ trang trọng của if you need, rất hay gặp trong email công việc.","But for và if it weren't for nghĩa là nếu không có. Với quá khứ dùng had it not been for.","Assuming, supposing, provided that thay cho if khi lập kế hoạch dựa trên một giả định.","Were it not for là đảo ngữ của if it weren't for, trang trọng hơn."],"examples":[{"en":"Should you need anything else, just let me know.","vi":"Nếu bạn cần thêm gì, cứ báo tôi."},{"en":"But for your help, we'd have failed.","vi":"Nếu không có sự giúp đỡ của bạn, chúng tôi đã thất bại."},{"en":"Assuming nothing goes wrong, we can start next week.","vi":"Giả sử không có gì trục trặc, tuần sau có thể bắt đầu."}],"mistake":{"wrong":"Should you will need help, call me.","right":"Should you need help, call me.","why":"Sau should you là động từ nguyên mẫu, không thêm will."},"lessons":[{"id":"ch03-l03","title":"Đảo ngữ trong câu điều kiện"},{"id":"ch03-l01","title":"Ba loại câu điều kiện"}]},{"stage":"c1-reporting-verbs","title":"Động từ tường thuật: insist on, urge, admit, suggest","points":["Thay said bằng động từ thể hiện thái độ: insist, urge, warn, admit, deny, suggest.","Insist on, deny, admit, suggest, recommend đi với động từ thêm ing: She denied taking it.","Urge, warn, encourage đi với tân ngữ rồi to cộng động từ: He warned me not to sign it.","Suggest không đi với tân ngữ rồi to: không nói suggest me to go."],"examples":[{"en":"He insisted on paying the bill.","vi":"Anh ấy nhất quyết trả tiền."},{"en":"She urged us to act quickly.","vi":"Cô ấy thúc giục chúng tôi hành động nhanh."},{"en":"She suggested postponing the trip.","vi":"Cô ấy đề xuất hoãn chuyến đi."}],"mistake":{"wrong":"She suggested me to take a break.","right":"She suggested that I take a break.","why":"Suggest không đi với tân ngữ cộng to. Dùng suggest that cộng mệnh đề, hoặc suggest cộng ing."},"lessons":[]},{"stage":"c1-diplomatic-disagreement","title":"Phản đối khéo léo","points":["With respect hoặc with all due respect mở đầu lời phản đối thẳng nhưng lịch sự với người cấp cao.","Thêm would hoặc not sure làm lời phản đối mềm hơn: I'm not sure I'd agree with that.","Câu hỏi phủ định couldn't we, wouldn't it be better đưa ra phương án khác mà không bác bỏ thẳng.","I see where you're coming from ghi nhận lý do của người kia trước khi đưa ý khác."],"examples":[{"en":"With respect, the data doesn't support that.","vi":"Với tất cả sự tôn trọng, số liệu không ủng hộ điều đó."},{"en":"Couldn't we look at other options instead?","vi":"Sao chúng ta không xem xét các phương án khác?"},{"en":"I see where you're coming from, but it's risky.","vi":"Tôi hiểu vì sao bạn nghĩ vậy, nhưng nó rủi ro."}],"mistake":{"wrong":"With all respect, you are wrong.","right":"With all due respect, I see it differently.","why":"Cụm cố định là with all due respect. Sau đó nên nói về quan điểm của bạn thay vì nói người kia sai."},"lessons":[]},{"stage":"c1-speculating-future","title":"Dự đoán tương lai: bound to, set to, will have done","points":["Be bound to cộng động từ: chắc chắn sẽ xảy ra. Be set to và be due to: đã lên kế hoạch, sắp xảy ra.","On the verge of và on the brink of cộng danh từ hoặc ing: đang rất gần một điều quan trọng.","Will have cộng quá khứ phân từ: sẽ xong trước một mốc. Will be cộng ing: sẽ đang làm vào lúc đó.","Mốc thời gian thường đi với by: by Friday, by next year."],"examples":[{"en":"It's bound to cause problems.","vi":"Chắc chắn nó sẽ gây ra rắc rối."},{"en":"We're on the verge of signing the deal.","vi":"Chúng tôi sắp sửa ký hợp đồng."},{"en":"By next year, we'll have doubled our users.","vi":"Đến năm sau, chúng ta sẽ tăng gấp đôi số người dùng."}],"mistake":{"wrong":"We're on the verge of sign the deal.","right":"We're on the verge of signing the deal.","why":"Sau giới từ of, động từ phải thêm ing."},"lessons":[]},{"stage":"c1-generalising","title":"Khái quát mà không quá đà","points":["By and large, on the whole, all in all đều nghĩa là nhìn chung, dùng cho nhận định đúng phần lớn.","Tend to cộng động từ nói về điều thường xảy ra, nhẹ hơn always và tránh khái quát quá mức.","Generally speaking, as a rule, for the most part cho người nghe biết vẫn có ngoại lệ.","There's a tendency to nhận xét thói quen chung mà không chỉ trích ai cụ thể."],"examples":[{"en":"By and large, the feedback was positive.","vi":"Nhìn chung, phản hồi tích cực."},{"en":"People tend to underestimate the cost.","vi":"Mọi người thường đánh giá thấp chi phí."},{"en":"Generally speaking, smaller teams move faster.","vi":"Nói chung, nhóm nhỏ làm nhanh hơn."}],"mistake":{"wrong":"People are tend to forget passwords.","right":"People tend to forget passwords.","why":"Tend là động từ thường, không đi với are. Chỉ dùng are khi nói are likely to."},"lessons":[]},{"stage":"c1-signposting","title":"Dẫn dắt người nghe khi trình bày","points":["Let me now turn to và moving on to báo hiệu bạn chuyển sang phần mới, giúp người nghe không bị lạc.","To put it another way, in other words, put simply dùng để nói lại một ý theo cách dễ hiểu hơn.","Which brings me to nối ý vừa nói với ý tiếp theo, nghe mạch lạc hơn nhiều so với and next.","Bị hỏi giữa chừng, nói I'll come back to that in a moment để giữ mạch mà vẫn lịch sự."],"examples":[{"en":"Let me now turn to the main risks.","vi":"Giờ tôi xin chuyển sang những rủi ro chính."},{"en":"To put it another way, we're losing money.","vi":"Nói cách khác, chúng ta đang lỗ."},{"en":"Which brings me to my next point.","vi":"Điều này đưa tôi đến với ý tiếp theo."}],"mistake":{"wrong":"Let me now turn to talk about the budget.","right":"Let me now turn to the budget.","why":"Turn to ở đây đi với danh từ, không cần thêm talk about vì nghĩa đã là chuyển sang nói về."},"lessons":[]},{"stage":"c1-cleft-sentences","title":"Câu chẻ: What I need is, It was ... who","points":["Câu chẻ tách một câu thành hai vế để dồn sự chú ý vào một phần: What worries me most is the deadline.","It was cộng phần cần nhấn cộng who hoặc that: It was Lan who found the mistake. Với người dùng who, với vật dùng that.","All I want is và the last thing we need is cũng là câu chẻ, nghe nhấn mạnh và giàu cảm xúc hơn câu thường.","Sau All I did was, All you have to do is có thể dùng động từ nguyên mẫu không to: All I did was ask."],"examples":[{"en":"What worries me most is the hidden costs.","vi":"Điều làm tôi lo nhất là các chi phí ẩn."},{"en":"It was my mentor who made the difference.","vi":"Chính người hướng dẫn của tôi đã tạo nên sự khác biệt."},{"en":"The last thing we need is another delay.","vi":"Điều chúng ta không hề muốn lúc này là thêm một lần trì hoãn."}],"mistake":{"wrong":"What I need it is more time.","right":"What I need is more time.","why":"Vế What I need đã là chủ ngữ, thêm it nữa là thừa chủ ngữ, lỗi rất hay gặp khi dịch từ tiếng Việt."},"lessons":[{"id":"ch14-l02","title":"Nhấn mạnh trong cách viết"}]},{"stage":"c1-constructive-criticism","title":"Góp ý khéo mà vẫn rõ ràng","points":["I'd question whether nêu nghi ngờ lịch sự, thay cho câu nói thẳng như This is wrong.","It might be worth cộng động từ thêm ing gợi ý một cách sửa, người nghe thấy được tôn trọng.","There's room for improvement nghĩa là đã ổn nhưng vẫn có thể tốt hơn, nhẹ nhàng hơn It's not good enough.","My only concern would be cho thấy nhìn chung bạn đồng ý, chỉ còn một điểm nhỏ cần xem lại."],"examples":[{"en":"I'd question whether the budget is realistic.","vi":"Tôi hơi băn khoăn liệu ngân sách có thực tế không."},{"en":"It might be worth getting a second opinion.","vi":"Có lẽ cũng nên hỏi thêm ý kiến người khác."},{"en":"There's room for a clearer structure.","vi":"Bố cục vẫn còn có thể rõ ràng hơn."}],"mistake":{"wrong":"It might be worth to check the figures again.","right":"It might be worth checking the figures again.","why":"Sau worth luôn dùng động từ thêm ing, không dùng to cộng động từ."},"lessons":[]},{"stage":"c1-past-criticism","title":"Trách móc và tiếc nuối chuyện đã qua","points":["Should have và ought to have cộng quá khứ phân từ: lẽ ra phải làm nhưng đã không làm.","Needn't have done: đã làm nhưng hóa ra không cần. Didn't need to do: không cần nên thường là đã không làm.","Was supposed to nói về điều đã hẹn hoặc dự kiến nhưng không thành: We were supposed to finish by Friday.","Could at least have trách nhẹ rằng người kia không làm cả điều tối thiểu: You could at least have said sorry."],"examples":[{"en":"You really ought to have told me sooner.","vi":"Lẽ ra bạn phải nói với tôi sớm hơn mới đúng."},{"en":"You needn't have gone to all that trouble.","vi":"Bạn đâu cần phải cất công như vậy."},{"en":"You could at least have sent a message.","vi":"Ít ra bạn cũng nên nhắn một tin chứ."}],"mistake":{"wrong":"You should told me earlier.","right":"You should have told me earlier.","why":"Nói về quá khứ phải dùng should have cộng quá khứ phân từ, không bỏ have."},"lessons":[{"id":"ch20-l22","title":"SHOULD + PERFECTIVE"}]},{"stage":"c1-probability","title":"Nói mức độ chắc chắn tinh tế","points":["In all likelihood và the odds are that: rất có thể. In all likelihood trang trọng hơn, the odds are that thân mật hơn.","There's every chance nghĩa là khả năng rất cao, thường mang ý lạc quan. A slim chance là khả năng rất thấp.","It's highly unlikely that phủ nhận khả năng một cách khách quan, nghe lịch sự hơn I don't think.","Ghép đúng cặp: highly likely, highly unlikely. Không nói very much likely."],"examples":[{"en":"In all likelihood, they'll say yes.","vi":"Rất có thể là họ sẽ đồng ý."},{"en":"There's every chance you'll get the job.","vi":"Hoàn toàn có khả năng bạn sẽ được nhận."},{"en":"It's highly unlikely that anyone will complain.","vi":"Rất khó có chuyện ai đó phàn nàn."}],"mistake":{"wrong":"There's a big chance it'll rain.","right":"There's a good chance it'll rain.","why":"Tiếng Anh nói a good chance hoặc a strong chance, không nói a big chance như dịch từ khả năng lớn."},"lessons":[]},{"stage":"c1-feelings","title":"Bày tỏ cảm xúc một cách tinh tế","points":["I can't help feeling cộng tính từ hoặc mệnh đề: cảm giác không kìm được. Sau help dùng động từ thêm ing.","I must admit, I have to say, to be honest giúp thừa nhận cảm xúc khó nói một cách chân thành.","It's been weighing on me hoặc playing on my mind: một chuyện cứ đè nặng trong lòng suốt một thời gian.","I'd be lying if I said I wasn't nervous là cách thú nhận gián tiếp, mềm hơn I'm nervous."],"examples":[{"en":"I can't help feeling a bit let down.","vi":"Tôi không khỏi cảm thấy hơi thất vọng."},{"en":"I must admit I'm quite impressed.","vi":"Phải thú thật là tôi khá ấn tượng."},{"en":"I'd be lying if I said I wasn't tempted.","vi":"Nói là không xiêu lòng thì là nói dối."}],"mistake":{"wrong":"I can't help to feel worried.","right":"I can't help feeling worried.","why":"Cấu trúc can't help luôn đi với động từ thêm ing, không dùng to cộng động từ."},"lessons":[]},{"stage":"c1-pros-cons","title":"Cân nhắc ưu và nhược điểm","points":["On the upside, on the plus side giới thiệu mặt tốt. The downside is, the main drawback is nêu mặt hạn chế.","The catch is dùng cho điểm bất lợi bị giấu kín, thường đi kèm một lời mời hấp dẫn.","What it boils down to is hoặc it all comes down to rút mọi thứ về một yếu tố cốt lõi.","Chốt lại bằng outweigh: The benefits outweigh the costs nghĩa là lợi nhiều hơn hại."],"examples":[{"en":"On the upside, there's no commute.","vi":"Mặt tích cực là không phải đi lại."},{"en":"The downside is that it takes longer.","vi":"Điểm trừ là nó mất nhiều thời gian hơn."},{"en":"What it boils down to is trust.","vi":"Rốt cuộc thì mọi chuyện nằm ở lòng tin."}],"mistake":{"wrong":"The benefits are outweigh the costs.","right":"The benefits outweigh the costs.","why":"Outweigh là động từ, không đi cùng are. Lỗi này hay gặp do nhầm với cấu trúc are greater than."},"lessons":[]},{"stage":"c1-summarising","title":"Tóm tắt và chốt lại ý chính","points":["In a nutshell, long story short, basically dùng khi kể lại ngắn gọn, nghe thân mật.","The bottom line is that và at the end of the day nêu điều quan trọng nhất, bỏ qua chi tiết phụ.","All things considered và on the whole đưa ra kết luận sau khi đã cân nhắc cả hai mặt.","The key takeaway is that là cách chốt thông điệp cuối buổi họp, rất hay dùng trong công việc."],"examples":[{"en":"In a nutshell, we need more time.","vi":"Nói gọn lại thì chúng ta cần thêm thời gian."},{"en":"The bottom line is that we can't afford it.","vi":"Điều cốt lõi là chúng ta không đủ tiền."},{"en":"All things considered, it went well.","vi":"Xét mọi mặt thì mọi việc diễn ra tốt."}],"mistake":{"wrong":"In conclusion, I think that's all.","right":"All things considered, it was a success.","why":"Câu kết cần nêu kết luận thật, không chỉ báo là đã hết. In conclusion cũng quá trang trọng khi nói."},"lessons":[]},{"stage":"c1-euphemism","title":"Nói giảm nói tránh cho tế nhị","points":["Not the most cộng tính từ tốt là cách chê khéo: He's not the most patient person thay cho He's impatient.","A little on the cộng tính từ cộng side làm lời nhận xét tiêu cực nhẹ đi: a little on the expensive side.","Let someone go, made redundant là cách nói tránh của fire. Between jobs là cách nói tế nhị của unemployed.","Passed away nhẹ nhàng hơn died, nên dùng khi nói về người đã mất."],"examples":[{"en":"He's not the most organised person.","vi":"Anh ấy không phải người ngăn nắp cho lắm."},{"en":"It's a little on the small side.","vi":"Nó hơi nhỏ một chút."},{"en":"They had to let some staff go.","vi":"Họ đã phải cho một số nhân viên nghỉ việc."}],"mistake":{"wrong":"He's not the most lazy person.","right":"He's not the most hardworking person.","why":"Muốn chê khéo thì phủ định một tính từ tốt. Phủ định tính từ xấu lại thành lời khen."},"lessons":[]},{"stage":"c1-tough-questions","title":"Xử lý câu hỏi khó một cách khéo léo","points":["That's a fair question ghi nhận câu hỏi, cho bạn thêm vài giây suy nghĩ và cho thấy bạn không né tránh.","I'd rather not speculate từ chối đoán khi chưa có căn cứ. Sau rather là động từ nguyên mẫu không to.","Let me get back to you on hẹn trả lời sau. Get back to someone nghĩa là liên lạc lại để trả lời.","What I can say is cho biết phần thông tin bạn được phép chia sẻ, lịch sự mà vẫn minh bạch."],"examples":[{"en":"That's a fair question, and the short answer is no.","vi":"Câu hỏi rất xác đáng, và câu trả lời ngắn gọn là không."},{"en":"Let me get back to you on the exact figures.","vi":"Để tôi trả lời bạn sau về số liệu chính xác."},{"en":"What I can say is your data is safe.","vi":"Điều tôi có thể nói là dữ liệu của bạn vẫn an toàn."}],"mistake":{"wrong":"I'd rather not to speculate about the numbers.","right":"I'd rather not speculate about the numbers.","why":"Sau would rather và would rather not dùng động từ nguyên mẫu, không có to."},"lessons":[]},{"stage":"c1-doubt-certainty","title":"Nghi ngờ và khẳng định chắc chắn","points":["I have my doubts about cộng danh từ diễn tả hoài nghi nhẹ, vẫn để ngỏ khả năng mình sai.","I'm far from convinced that mạnh hơn I'm not sure: bạn còn rất nghi ngờ nhưng vẫn lịch sự.","There's no doubt that và there's no question that khẳng định chắc chắn, dùng khi có bằng chứng rõ.","I'd be very surprised if cộng động từ quá khứ là cách nói khéo của I don't think so."],"examples":[{"en":"I have my doubts about their figures.","vi":"Tôi có phần nghi ngờ về số liệu của họ."},{"en":"There's no doubt that prices will rise.","vi":"Không còn nghi ngờ gì nữa, giá sẽ tăng."},{"en":"I'd be very surprised if they agreed.","vi":"Tôi sẽ rất ngạc nhiên nếu họ đồng ý."}],"mistake":{"wrong":"There's no doubt about that prices will rise.","right":"There's no doubt that prices will rise.","why":"Trước một mệnh đề chỉ dùng that. About chỉ đi với danh từ: no doubt about it."},"lessons":[]},{"stage":"c1-strong-emphasis","title":"Nhấn mạnh bằng cụm cố định","points":["By no means nghĩa là hoàn toàn không, mạnh hơn not: It's by no means perfect.","Not in the slightest và not in the least nghĩa là không một chút nào, đặt sau động từ hoặc cuối câu.","Utterly và absolutely đi với tính từ mạnh như ridiculous, exhausted. Không nói very ridiculous.","The last thing I want is to nghĩa là điều tôi ít muốn nhất, hay dùng để trấn an người nghe."],"examples":[{"en":"It's by no means easy.","vi":"Nó chẳng hề dễ dàng."},{"en":"I'm not worried in the slightest.","vi":"Tôi chẳng lo lắng chút nào."},{"en":"The last thing I want is to upset anyone.","vi":"Điều tôi không muốn nhất là làm ai đó buồn lòng."}],"mistake":{"wrong":"That's very ridiculous.","right":"That's utterly ridiculous.","why":"Ridiculous đã là tính từ mạnh nên không đi với very. Hãy dùng utterly hoặc absolutely."},"lessons":[{"id":"ch14-l02","title":"Nhấn mạnh trong cách viết"}]},{"stage":"c1-narrative-inversion","title":"Đảo ngữ khi kể chuyện: little did I know","points":["Little did I know tạo bất ngờ khi kể chuyện. Sau little là did cộng chủ ngữ cộng động từ nguyên mẫu.","No sooner had I cộng V3 đi với than. Hardly had I cộng V3 đi với when. Cả hai nghĩa là vừa mới thì.","Only later did I kể điều mình hiểu ra sau sự việc. Đảo ngữ nằm ngay sau only later.","Vế xảy ra trước dùng quá khứ hoàn thành, vế xảy ra sau dùng quá khứ đơn."],"examples":[{"en":"Little did I know that she was my boss.","vi":"Tôi nào ngờ rằng cô ấy là sếp của tôi."},{"en":"No sooner had I left the house than it rained.","vi":"Tôi vừa ra khỏi nhà thì trời đổ mưa."},{"en":"Hardly had we got home when the phone rang.","vi":"Chúng tôi vừa mới về đến nhà thì điện thoại reo."}],"mistake":{"wrong":"No sooner had I arrived when it started raining.","right":"No sooner had I arrived than it started raining.","why":"No sooner luôn đi với than vì sooner là dạng so sánh. Hardly mới đi với when."},"lessons":[{"id":"ch18-l18","title":"Phép đảo chủ ngữ và động từ sau các trạng từ"},{"id":"ch01-l07","title":"Thì quá khứ hoàn thành/ Tiền quá khứ"}]},{"stage":"c1-formal-register","title":"Văn phong trang trọng và danh từ hóa","points":["Danh từ hóa biến động từ thành danh từ: we implemented thành the implementation of, câu khách quan hơn.","Following, prior to, in light of, in view of thay cho after, before, because of trong văn bản công việc.","A significant increase in sales trang trọng hơn sales went up a lot. Sau increase, decline dùng in.","Bị động như has been delayed giúp tập trung vào sự việc thay vì người làm."],"examples":[{"en":"The implementation of the new system has been delayed.","vi":"Việc triển khai hệ thống mới đã bị hoãn lại."},{"en":"In light of your feedback, we will revise the plan.","vi":"Xét đến góp ý của bạn, chúng tôi sẽ điều chỉnh kế hoạch."},{"en":"There has been a significant decline in sales.","vi":"Doanh số đã có sự sụt giảm đáng kể."}],"mistake":{"wrong":"There has been a significant increase of sales.","right":"There has been a significant increase in sales.","why":"Nói tăng hay giảm ở lĩnh vực nào thì dùng increase in, decline in, không dùng of."},"lessons":[]},{"stage":"c1-idioms-work","title":"Thành ngữ thông dụng trong công việc","points":["Get the ball rolling là khởi động một việc. Kick things off cũng có nghĩa tương tự.","Back to square one và back to the drawing board nghĩa là phải làm lại từ đầu.","On the same page là cùng hiểu, cùng thống nhất. Keep someone in the loop là cập nhật tin cho ai.","Thành ngữ hợp với giao tiếp hằng ngày ở công sở, nhưng nên hạn chế trong văn bản rất trang trọng."],"examples":[{"en":"Let's get the ball rolling on the new project.","vi":"Hãy bắt tay vào dự án mới thôi."},{"en":"We're back to square one with the design.","vi":"Với bản thiết kế, chúng ta lại về vạch xuất phát."},{"en":"I'll keep you in the loop about any changes.","vi":"Tôi sẽ cập nhật cho bạn về mọi thay đổi."}],"mistake":{"wrong":"Are we on the same paper about the deadline?","right":"Are we on the same page about the deadline?","why":"Thành ngữ là cụm cố định, không thay từ: on the same page, không phải same paper."},"lessons":[{"id":"ch27-l01","title":"THÀNH NGỮ"}]},{"stage":"c1-hypothetical-past-present","title":"Câu điều kiện hỗn hợp và wish","points":["Quá khứ dẫn đến hiện tại: If I hadn't moved abroad, I wouldn't be here. Vế sau dùng would cộng động từ nguyên mẫu.","Hiện tại dẫn đến quá khứ: If I were more confident, I'd have said yes. Vế sau dùng would have cộng V3.","I wish I'd cộng V3 là tiếc nuối về quá khứ. I wish cộng quá khứ đơn là tiếc nuối về hiện tại.","Had I cộng V3 là dạng đảo ngữ trang trọng của If I had cộng V3."],"examples":[{"en":"If I hadn't learned English, I wouldn't be here.","vi":"Nếu hồi đó tôi không học tiếng Anh thì giờ tôi đã chẳng ở đây."},{"en":"If I were more adventurous, I'd have said yes.","vi":"Nếu tôi thích phiêu lưu hơn thì đã nhận lời rồi."},{"en":"I wish I'd travelled more when I had the chance.","vi":"Giá mà tôi đã đi du lịch nhiều hơn khi còn cơ hội."}],"mistake":{"wrong":"If I had taken that job, I would have been rich now.","right":"If I had taken that job, I would be rich now.","why":"Kết quả ở hiện tại, có now, nên dùng would be chứ không dùng would have been."},"lessons":[{"id":"ch03-l01","title":"Ba loại câu điều kiện"},{"id":"ch04-l03","title":"Ao ước ở quá khứ"}]}]`),c=Object.values([o,a,g,s,l]).flat(),r=t=>c.find(h=>h.stage===t);function m(){const t=[],h=new Set;for(const n of e){if(h.has(n.topic))continue;h.add(n.topic);const i=r(n.topic);i&&t.push({...i,level:n.level,stageTitle:n.topic_vi})}return t}export{m as a,r as t};
